class AppTest {

    private val userDirectory = System.getProperty("user.dir")
    private val userDirPath = Path.of(userDirectory)
    private val testResourcesPath = userDirPath
        .resolve("src")
        .resolve("test")
        .resolve("resources")

    private fun rootsOf(
        testDir: String,
        testFiles: List<String>,
        from: List<String> = emptyList(),
        boundaries: List<String> = emptyList(),
        pures: List<String> = emptyList()
    ): List<GraphBuilderBlock> {
        val testDirPath = testResourcesPath.resolve(testDir)
        return AstReader(testResourcesPath).process(testFiles.map { testDirPath.resolve(it) }, from, boundaries, pures)
    }

    private fun mermaid(roots: List<GraphBuilderBlock>): List<String> {
        val result = ArrayList<String>()
        MermaidExporter()
            .processMainMethod(roots) { result.add(it) }
        return result
    }

    private fun buildGraph(
        testDir: String,
        testFiles: List<String>,
        from: List<String> = emptyList(),
        boundaries: List<String> = emptyList()
    ): List<String> = mermaid(rootsOf(testDir, testFiles, from, boundaries))

    /**
     * The GraphML rendering, parsed.
     *
     * Parsing with a real XML parser rather than matching text is the point: a label that is XML
     * syntax has to come back out as its own characters, and the document has to be something a
     * viewer can actually open.
     */
    private fun buildGraphml(testDir: String, testFiles: List<String>): Document {
        val testDirPath = testResourcesPath.resolve(testDir)
        val testFilePaths = testFiles.map { testDirPath.resolve(it) }
        val roots = AstReader(testResourcesPath).process(testFilePaths)

        val text = StringBuilder()
        GraphmlExporter()
            .processMainMethod(roots) { text.append(it).append("\n") }
        return DocumentBuilderFactory.newInstance()
            .newDocumentBuilder()
            .parse(ByteArrayInputStream(text.toString().toByteArray()))
    }

    /** The JSON rendering, parsed with a library that did not write it. */
    private fun buildJson(testDir: String, testFiles: List<String>): JsonObject {
        val testDirPath = testResourcesPath.resolve(testDir)
        val testFilePaths = testFiles.map { testDirPath.resolve(it) }
        val roots = AstReader(testResourcesPath).process(testFilePaths)

        val text = StringBuilder()
        JsonExporter(testResourcesPath).processMainMethod(roots) { text.append(it).append("\n") }
        return JsonParser.parseString(text.toString()).asJsonObject
    }

    /** The summaries document, as text. */
    private fun rawSummaries(testDir: String, from: List<String> = emptyList(), boundaries: List<String> = emptyList()): String {
        val testDirPath = testResourcesPath.resolve(testDir)
        val files = Files.list(testDirPath).use { stream -> stream.filter { it.toString().endsWith(".java") }.sorted().toList() }
        return SummariesExporter().export(AstReader(testResourcesPath).summarise(files, from, boundaries))
    }

    private fun buildSummaries(testDir: String, from: List<String> = emptyList(), boundaries: List<String> = emptyList()): JsonObject =
        JsonParser.parseString(rawSummaries(testDir, from, boundaries)).asJsonObject

    private fun summaryRows(doc: JsonObject) = doc.getAsJsonArray("methods").map { it.asJsonObject }

    private fun flowsOf(doc: JsonObject, method: String) = summaryRows(doc).single { it.get("method").asString == method }
        .getAsJsonArray("flows").map { it.asJsonArray.let { pair -> "${pair[0].asString}>${pair[1].asString}" } }

    @Test
    fun summariesListEveryMethodWithItsFlows() {
        val doc = buildSummaries("funcCall")
        assertEquals("codeflow-summaries", doc["format"].asString)
        val names = summaryRows(doc).map { it.get("method").asString }
        assertEquals(
            listOf(
                "test.App#main(java.lang.String[])", "test.App#methodA(int,int)", "test.App#methodB()",
                "test.App#methodC(int)"
            ),
            names
        )
        assertEquals(listOf("P0>RET"), flowsOf(doc, "test.App#methodC(int)"))
        assertEquals(listOf("P0>RET", "P1>RET"), flowsOf(doc, "test.App#methodA(int,int)"))
        assertEquals(names.size, doc.getAsJsonObject("counts")["methods"].asInt)
    }

    @Test
    fun summariesAreByteStableAcrossRuns() =
        assertEquals(rawSummaries("objectArgument"), rawSummaries("objectArgument"))

    /**
     * `Source#read` has no body, so it is not a source method and cannot be a root; a caller going
     * through it must still summarise, with the dispatch resolved on the object.
     */
    @Test
    fun summariesOfAnAbstractMethodAreEmptyNotACrash() {
        val doc = buildSummaries("abstractMethod")
        assertEquals(
            listOf("abstractMethod.App#main(java.lang.String[])", "abstractMethod.Doubling#read(int)"),
            summaryRows(doc).map { it.get("method").asString }
        )
        assertEquals(listOf("P0>RET"), flowsOf(doc, "abstractMethod.Doubling#read(int)"))
        assertFailsWith<GraphException> { rawSummaries("abstractMethod", listOf("Source#read")) }
    }

    /**
     * A gap is the "no silently missing flow" guarantee: it has to arrive with its kind, a position and
     * a detail, and `counts.gaps` has to say how many of each kind the rows hold.
     */
    @Test
    fun aSummaryWithAGapSaysWhereAndCountsIt() {
        val doc = buildSummaries("templateMethod")
        val gaps = summaryRows(doc).flatMap { it.getAsJsonArray("gaps").map { gap -> gap.asJsonObject } }
        assertEquals(listOf("dispatch"), gaps.map { it.get("kind").asString })
        assertTrue(Regex("""[\w/]*App\.java:\d+:\d+""").matches(gaps.single().get("at").asString), gaps.single().toString())
        assertEquals("Base#step on this", gaps.single().get("detail").asString)
        assertEquals(gaps.size, doc.getAsJsonObject("counts").getAsJsonObject("gaps")["dispatch"].asInt)
        assertEquals(setOf("dispatch"), doc.getAsJsonObject("counts").getAsJsonObject("gaps").keySet())
    }

    @Test
    fun fromNarrowsTheSummariesToTheMethodsNamed() {
        val all = buildSummaries("funcCall")
        val one = buildSummaries("funcCall", listOf("App#methodA"))
        assertEquals(listOf("test.App#methodA(int,int)"), summaryRows(one).map { it.get("method").asString })
        assertEquals(1, one.getAsJsonObject("counts")["methods"].asInt)
        assertEquals(flowsOf(all, "test.App#methodA(int,int)"), flowsOf(one, "test.App#methodA(int,int)"))
        assertTrue(summaryRows(all).size > 1)
    }

    @Test
    fun summariesRefuseAFromThatMatchesNothing() {
        assertFailsWith<GraphException> { rawSummaries("funcCall", listOf("App#nope")) }
    }

