    private fun jsonNodes(doc: JsonObject) = doc.getAsJsonArray("nodes").map { it.asJsonObject }

    private fun jsonLabel(node: JsonObject) = node.get("label").asString

    private fun jsonParent(node: JsonObject) = node.get("parent")?.asString

    private fun jsonSource(node: JsonObject) = node.get("source")?.asString

    /** The JSON edges as (source label, target label) pairs, to compare against [edgeLabels]. */
    private fun jsonEdgeLabels(doc: JsonObject): List<Pair<String, String>> {
        val labels = jsonNodes(doc).associate { it.get("id").asString to jsonLabel(it) }
        return doc.getAsJsonArray("edges").map { it.asJsonObject }.map {
            (labels[it.get("source").asString] ?: "?") to (labels[it.get("target").asString] ?: "?")
        }
    }

    private fun elements(doc: Document, tag: String): List<Element> {
        val found = doc.getElementsByTagName(tag)
        return (0 until found.length).map { found.item(it) as Element }
    }

    /** A node's own `data`, not that of the nodes nested inside it. */
    private fun dataOf(node: Element, key: String): String? {
        val children = node.childNodes
        return (0 until children.length)
            .mapNotNull { children.item(it) as? Element }
            .firstOrNull { it.tagName == "data" && it.getAttribute("key") == key }
            ?.textContent
    }

    private fun labelOf(node: Element) = dataOf(node, "label") ?: ""

    /** The label of the block this node is nested in, or null for the outermost one. */
    private fun enclosingBlockLabel(node: Element): String? {
        var ancestor = node.parentNode
        while (ancestor != null) {
            if (ancestor is Element && ancestor.tagName == "node") return labelOf(ancestor)
            ancestor = ancestor.parentNode
        }
        return null
    }

    /** The GraphML edges as (source label, target label) pairs, to compare against [edgeLabels]. */
    private fun graphmlEdgeLabels(doc: Document): List<Pair<String, String>> {
        val labels = elements(doc, "node").associate { it.getAttribute("id") to labelOf(it) }
        return elements(doc, "edge").map {
            (labels[it.getAttribute("source")] ?: "?") to (labels[it.getAttribute("target")] ?: "?")
        }
    }

    /**
     * A node's label as the source wrote it: a bold lead's markdown string - ``"`**call** f`"``, see
     * `MermaidExporter.caption` - read back as `call f`, so a test names a boundary call by its label.
     */
    private fun plain(label: String): String {
        val markdown = Regex("""^"`(.*)`"$""").find(label) ?: return label
        return markdown.groupValues[1].replace("**", "").replace("\\_", "_")
    }

    /** The declared nodes as (label, type) pairs, ignoring the generated ids. */
    private fun nodeTypes(graph: List<String>): List<Pair<String, String>> {
        val declaration = Regex("""^\s*n\d+\[([^]]*)]:::(\w+)$""")
        return graph.mapNotNull { line ->
            declaration.find(line)?.let { plain(it.groupValues[1]) to it.groupValues[2] }
        }
    }

    /**
     * The arrow between two nodes, with the optional `|kind|` an edge carries when it is not plain
     * flow. Written out once because three separate assertions parse edges and all three stopped
     * matching the moment a condition edge gained a label.
     */
    private val arrow = """ (?:-->(?:\|\w+\|)?|-\. \w+ \.->) """

    /**
     * [arrow] without `-. order .->`: the boundary-order token's edges say a call ran first, not that
     * a value went there - see [EdgeKind.ORDER] - so a walk asking where a value goes does not cross them.
     */
    private val dataArrow = """ (?:-->(?:\|\w+\|)?|-\. shared \.->) """

    /**
     * [arrow] without `-. event .->`: an entry point's event starts every node nothing else feeds -
     * see [EdgeKind.EVENT] - and an assertion on which labels are adjacent is about the code, not that.
     */
    private val codeArrow = """ (?:-->(?:\|\w+\|)?|-\. (?:shared|order) \.->) """

    /** The graph's edges as (source label, target label) pairs, ignoring the generated ids - and the event's, unless [events]. */
    private fun edgeLabels(graph: List<String>, events: Boolean = false): List<Pair<String, String>> {
        val edge = Regex("""n\d+\[([^]]*)]:::\w+${if (events) arrow else codeArrow}n\d+\[([^]]*)]""")
        return graph.mapNotNull { line ->
            edge.find(line)?.let { plain(it.groupValues[1]) to plain(it.groupValues[2]) }
        }
    }

    /**
     * Whether a value can reach another node by following edges.
     *
     * Labels alone cannot answer this when two distinct variables share a name, which is exactly
     * the case worth testing, so this walks the ids and only uses labels for the two endpoints.
     * Data only, as [TestFixtures.reaches] is: see [dataArrow].
     */
    private fun reaches(graph: List<String>, fromLabel: String, toLabel: String): Boolean {
        val edge = Regex("""(n\d+)\[([^]]*)]:::\w+${dataArrow}(n\d+)\[([^]]*)]""")
        val edges = graph.mapNotNull { edge.find(it) }
        val outgoing = edges.groupBy({ it.groupValues[1] }, { it.groupValues[3] })
        val labelOf = HashMap<String, String>()
        edges.forEach {
            labelOf[it.groupValues[1]] = plain(it.groupValues[2])
            labelOf[it.groupValues[3]] = plain(it.groupValues[4])
        }
        val seen = HashSet<String>()
        val queue = ArrayDeque(labelOf.filterValues { it == fromLabel }.keys)
        while (queue.isNotEmpty()) {
            val id = queue.removeFirst()
            if (!seen.add(id)) continue
            if (labelOf[id] == toLabel && seen.size > 1) return true
            outgoing[id]?.forEach { queue.addLast(it) }
        }
        return false
    }

    /**
     * The same graph as one interactive page and a JSON payload, written next to the source it was drawn from.
     *
     * Neither is a golden file: both are gitignored and rewritten on every run, for the same reason
     * [codeflow.ir.LoweringTest.write] writes `ir.txt`. `graph.html` is there to be looked at and
     * nothing reads it; `graph.json` is what the viewer's Node sweeps read, which is why this suite
     * has to have run before `npm test` means anything - `corpus.mjs` says so when it has not.
     * `snapshot.md` is the diagram as text, which is what a snapshot can compare, but it is not the
     * rendering a reader of a real corpus gets - a fixture's Mermaid is small enough to read as
     * source only because the fixture is small, and the viewer is what the tool is actually pointed
     * at. Having both next to `App.java` and `ir.txt` means a surprise can be traced from source to
     * meaning to document to what is on screen without running anything.
     *
     * Written on every run rather than only when missing, because a stale one would be worse than
     * none. The page is self-contained and about two megabytes of bundled library - the price of the
     * file opening from disk with no server, and the reason it is not committed.
     */
    private fun writePage(testDirPath: Path, roots: List<GraphBuilderBlock>) {
        val page = StringBuilder()
        HtmlExporter("reactflow.bundle.js", testResourcesPath).processMainMethod(roots) { page.append(it).append("\n") }
        Files.writeString(testDirPath.resolve("graph.html"), page)

        // The same payload the page inlines, on its own, because the viewer's Node tests need it:
        // model.ts decides what is on screen and a sweep over the real corpus is the only thing
        // that can say a fixture is reachable at all. Gitignored and rewritten like the page.
        val payload = StringBuilder()
        JsonExporter(testResourcesPath).processMainMethod(roots) { payload.append(it).append("\n") }
        Files.writeString(testDirPath.resolve("graph.json"), payload)
    }

    private fun codeflow(
        testDir: String,
        testFiles: List<String>,
        from: List<String> = emptyList(),
        boundaries: List<String> = emptyList()
    ) {
        val testDirPath = testResourcesPath.resolve(testDir)
        val roots = rootsOf(testDir, testFiles, from, boundaries)
        val result = mermaid(roots)
        writePage(testDirPath, roots)

        // The snapshot is only written when it does not exist yet, or when explicitly asked for.
        // Rewriting it on every mismatch would let a regression overwrite the expectation and pass
        // on the next run.
        val snapshotPath = testDirPath.resolve("snapshot.md")
        if (!Files.exists(snapshotPath) || System.getenv("UPDATE_SNAPSHOTS") == "1") {
            Files.write(snapshotPath, result)
        }
        assertEquals(
            Files.readAllLines(snapshotPath), result,
            "Graph for '$testDir' does not match snapshot.md. Re-run with UPDATE_SNAPSHOTS=1 to accept the new output."
        )

        assertNoSelfEdges(testDir, result)
        assertNoUnknownOperators(testDir, result)
        assertNoDuplicateNodeIds(testDir, result)
        assertNoNodeIsMentionedBelowItsOwnBlock(testDir, result)
        assertLinkStylesAddressTheEdgesTheyMean(testDir, result)
    }

    /**
     * Every `linkStyle` colours the edge whose kind asked for it, and no other.
     *
     * `linkStyle` indexes links globally across the whole flowchart in declaration order, so the
     * index of an edge is only settled once every nested block has been walked - and it is settled
     * again, differently, by anything that changes where an edge is written. Placing an edge in the
     * block enclosing both its endpoints did exactly that. A stale index is silent: it paints a
     * condition's grey onto some unrelated arrow and leaves the real one black, and the diagram
     * still renders.
     *
     * Derived from the document rather than from the exporter's counter, so it fails if the counter
     * and the writing ever disagree - which is the only way this can go wrong.
     */
    private fun assertLinkStylesAddressTheEdgesTheyMean(testDir: String, graph: List<String>) {
        val strokes = mapOf("true" to "#2e7d32", "false" to "#c62828", "if" to "#6a6a6a", "order" to "#7b1fa2", "event" to "#00897b")
        val edge = Regex("""n\d+\[[^]]*]:::\w+ (?:-->(?:\|(\w+)\|)?|-\. (\w+) \.->) n\d+\[""")
        val style = Regex("""^\s*linkStyle (\d+) stroke:(#\w+)""")
        val wanted = HashMap<Int, String>()
        val found = HashMap<Int, String>()
        var index = 0
        for (line in graph) {
            edge.find(line)?.let { match ->
                strokes[match.groupValues[1].ifEmpty { match.groupValues[2] }]?.let { wanted[index] = it }
                index++
                return@let
            }
            style.find(line)?.let { found[it.groupValues[1].toInt()] = it.groupValues[2] }
        }
        assertEquals(
            wanted, found,
            "Graph for '$testDir' styles links by an index that does not address the edge that asked " +
                    "for it, so a marked edge is drawn plain and a plain one is coloured."
        )
    }

    /**
     * A node is never named inside a subgraph deeper than the one it is declared in.
     *
     * Mermaid works out which subgraph a node belongs to from the statements naming it, and the
     * deeper claim wins: a node declared in `main` and then named by an edge written inside a
     * callee's subgraph is *drawn inside the callee*. `int b = classify(a, 10)` had exactly that -
     * `b` is main's local, and the edge from the callee's RETURN was written in the callee, so the
     * variable holding the call's result was drawn as though it lived inside the method it called.
     *
     * A box on this diagram is a method, and a value drawn in the wrong one is the graph being
     * confidently, readably wrong about where a value lives - with the arrows all still correct, so
     * nothing looks amiss. Naming a node from an *ancestor* is safe and stays allowed: that is where
     * an argument edge is written, and the declaration below still wins.
     */
    private fun assertNoNodeIsMentionedBelowItsOwnBlock(testDir: String, graph: List<String>) {
        val open = Regex("""^\s*subgraph (b\d+)\[""")
        val declaration = Regex("""^\s*(n\d+)\[[^]]*]:::\w+$""")
        val mention = Regex("""(n\d+)\[""")
        val parent = HashMap<String, String?>()
        val declaredIn = HashMap<String, String>()
        val mentions = ArrayList<Triple<String, String, String>>()
        val stack = ArrayDeque<String>()
        for (line in graph) {
            open.find(line)?.let {
                val block = it.groupValues[1]
                parent[block] = stack.lastOrNull()
                stack.addLast(block)
                return@let
            }
            if (line.trim() == "end") {
                stack.removeLastOrNull()
                continue
            }
            val here = stack.lastOrNull() ?: continue
            declaration.find(line)?.let { declaredIn[it.groupValues[1]] = here; return@let }
            if (declaration.containsMatchIn(line)) continue
            mention.findAll(line).forEach { mentions.add(Triple(it.groupValues[1], here, line.trim())) }
        }

        fun enclosesOrIs(outer: String, inner: String): Boolean {
            var block: String? = inner
            while (block != null) {
                if (block == outer) return true
                block = parent[block]
            }
            return false
        }

        val escaped = mentions.filter { (id, where, _) ->
            val declared = declaredIn[id] ?: return@filter false
            !enclosesOrIs(where, declared)
        }
        assertTrue(
            escaped.isEmpty(),
            "Graph for '$testDir' names a node inside a block below the one declaring it, which " +
                    "draws it in the wrong method: ${escaped.map { "${it.first} in ${it.second}: ${it.third}" }}"
        )
    }

    /**
     * A node with an edge to itself means two different AST nodes were given the same id and so
     * were merged into one. Nothing in the language produces a value that flows into itself.
     */
    private fun assertNoSelfEdges(testDir: String, graph: List<String>) {
        val edge = Regex("""n(\d+)\[[^]]*]:::\w+${arrow}n(\d+)\[""")
        val selfEdges = graph.filter { line ->
            val match = edge.find(line)
            match != null && match.groupValues[1] == match.groupValues[2]
        }
        assertTrue(selfEdges.isEmpty(), "Graph for '$testDir' has nodes with an edge to themselves: $selfEdges")
    }

    /**
     * Two nodes rendered under one id are drawn as one box, and every edge of both lands on it, so
     * the diagram claims values flow between things that never touched. Identity used to be a hash
     * of the node's label and call stack, which could always collide; it is now a serial handed out
     * at creation, which cannot. This is here to notice if a derived id is ever reintroduced.
     *
     * Only the declaration lines are checked. The exporter repeats a node's full string on every
     * edge line it appears in, which is not a duplicate declaration.
     */
    private fun assertNoDuplicateNodeIds(testDir: String, graph: List<String>) {
        val declaration = Regex("""^\s*(n\d+)\[[^]]*]:::\w+$""")
        val ids = graph.mapNotNull { declaration.find(it)?.groupValues?.get(1) }
        val duplicates = ids.groupBy { it }.filterValues { it.size > 1 }.keys
        assertTrue(duplicates.isEmpty(), "Graph for '$testDir' declares the same node id twice: $duplicates")
    }

    /** An unlabelled operator makes the graph of a calculation unreadable. */
    private fun assertNoUnknownOperators(testDir: String, graph: List<String>) {
        val unknown = graph.filter { it.contains("[UNKNOWN]") }
        assertTrue(unknown.isEmpty(), "Graph for '$testDir' has unlabelled operators: $unknown")
    }

    /**
     * Both branches of `cond ? a : b` produce the value of the expression and the condition picks
     * between them, so all three have to reach the result. Anything less silently drops a value
     * that the code really can produce: for a guarded division it hides either the guard or the
     * fallback.
     */
    @Test
    fun ternaryConnectsBothBranchesAndCondition() {
        val edges = edgeLabels(buildGraph("ternary", listOf("App.java")))
        assertTrue("==" to "ternary" in edges, "condition does not reach the selection: $edges")
        assertTrue("fallback" to "ternary" in edges, "true branch does not reach the selection: $edges")
        assertTrue("div" to "ternary" in edges, "false branch does not reach the selection: $edges")
        assertTrue("ternary" to "guarded" in edges, "selection does not reach the variable: $edges")
    }

    /**
     * A value written in one branch of an `if` and one written before it both reach a use below it.
     *
     * `if (b == 7) { b = 13; } else { a = 17; }` leaves `c = b` able to hold 5 or 13 and `d = a` able
     * to hold 5 or 17, and the diagram used to claim each could hold only one - the value from
     * whichever branch was walked last. That is the failure this project is arranged around: not an
     * error, not a gap, a complete-looking graph asserting a flow the program does not have and
     * missing one it does.
     *
     * Asked with [reaches] rather than on adjacent edges because the join is a box of its own: `13`
     * arrives at `c` through the phi for `b`, which is the point.
     */
    @Test
    fun bothPathsOfABranchReachAUseAfterIt() {
        val graph = buildGraph("if1", listOf("App.java"))
        assertTrue(reaches(graph, "13", "c"), "the value written in the branch does not reach 'c'")
        assertTrue(reaches(graph, "5", "c"), "the value written before the branch does not reach 'c'")
        assertTrue(reaches(graph, "17", "d"), "the value written in the branch does not reach 'd'")
        assertTrue(reaches(graph, "5", "d"), "the value written before the branch does not reach 'd'")
    }

    /**
     * The condition of an `if` reaches every join it decides, as the condition of a `?:` already does.
     *
     * `b == 7` is what picks between the two values each of `a` and `b` can hold below the branch,
     * and it used to be drawn with both operands flowing in and no edge leaving it at all - the
     * value the whole branch turns on, sitting on the page as though nothing consumed it. The join
     * boxes had the mirror problem: labelled with the variable's name, they were three boxes called
     * `a` in a row and nothing said which one was the choice.
     *
     * This is the same claim [ternaryConnectsBothBranchesAndCondition] makes about the expression
     * form, down to the shape: there the choice is a `ternary` box feeding the variable it was
     * assigned to, and here it is an `if` box feeding `a` and `b`. Writing the choice as a
     * statement rather than an expression is not a reason to draw it differently - so the join is
     * two boxes, the choosing and the variable that results, and `final int d = a` reads the
     * latter.
     */
    @Test
    fun theConditionOfAnIfReachesEachValueItDecides() {
        val graph = buildGraph("if1", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertEquals(2, edges.count { it == "==" to "if" }, "the condition does not reach both joins: $edges")
        assertTrue("if" to "a" in edges, "the choice does not reach the variable it decides: $edges")
        assertTrue("if" to "b" in edges, "the choice does not reach the variable it decides: $edges")
        assertTrue("a" to "d" in edges, "the joined variable does not reach the use below it: $edges")
        assertTrue("b" to "c" in edges, "the joined variable does not reach the use below it: $edges")
        assertTrue(reaches(graph, "13", "if"), "the value written in the branch does not reach a join")
        assertTrue(reaches(graph, "17", "if"), "the value written in the branch does not reach a join")
    }

    /**
     * The two paths into a join are told apart, and so are the two arms of a `?:`.
     *
     * A gated join takes three things and they are not interchangeable: the value if the branch was
     * taken, the value if it was not, and the test. Drawn as three identical arrows the box says
     * "one of these" and stops there, which is the reader having to go back to the source to learn
     * the one thing the diagram was supposed to save them.
     *
     * Counted rather than merely searched for, so that a run marking every edge - or none - fails.
     * `if1` has two joins, each with one path from each side of the branch.
     */
    @Test
    fun theTwoPathsOfAChoiceAreToldApart() {
        val branch = buildGraph("if1", listOf("App.java"))
        assertEquals(2, branch.count { it.contains("-->|true|") }, "the true paths are not marked: $branch")
        assertEquals(2, branch.count { it.contains("-->|false|") }, "the false paths are not marked: $branch")
        assertEquals(2, branch.count { it.contains("-->|if|") }, "the conditions are not marked: $branch")

        val expression = buildGraph("ternary", listOf("App.java"))
        assertEquals(1, expression.count { it.contains("-->|true|") }, "the true arm is not marked: $expression")
        assertEquals(1, expression.count { it.contains("-->|false|") }, "the false arm is not marked: $expression")
        assertEquals(1, expression.count { it.contains("-->|if|") }, "the condition is not marked: $expression")
    }

    /**
     * The selector of a `switch` statement reaches the join below it, for the same reason.
     *
     * Which arm ran is decided by the selector, so a join that does not take it is a diagram of a
     * `switch` with nothing on it saying what was switched on. The arms' own `==` comparisons stay
     * where they are - the join is gated by the selector rather than by each arm's test, which is
     * coarser and is the honest thing to draw without threading case labels through.
     */
    @Test
    fun theSelectorOfASwitchReachesTheJoinItDecides() {
        val graph = buildGraph("switchStatement", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("selector" to "switch" in edges, "the selector does not reach the join: $edges")
        assertTrue("switch" to "chosen" in edges, "the choice does not reach the variable it decides: $edges")
        assertTrue("switch" to "side" in edges, "the choice does not reach the variable it decides: $edges")
        assertTrue(reaches(graph, "switch", "+"), "the join does not reach the use below it: $edges")
    }

    /**
     * A loop body runs some number of times including none, and every count has to be on the page.
     *
     * `int y = 0; for (...) { y = 7; } int z = y;` gives `z` either 0 or 7, and the loop was drawn
     * straight through - `z` took the 7 and nothing else, which reads as "this loop always runs".
     * The counter had the mirror problem: `i++` produced a box with no edge leaving it, so the
     * value the condition tests on every iteration but the first came from nowhere.
     */
    @Test
    fun aValueFromBeforeALoopAndOneFromInsideItBothReachAUseAfterIt() {
        val graph = buildGraph("forLoop", listOf("App.java"))
        assertTrue(reaches(graph, "7", "z"), "the value written in the loop does not reach 'z'")
        assertTrue(reaches(graph, "0", "z"), "the value from before the loop does not reach 'z'")
        assertTrue(reaches(graph, "postInc", "<"), "the incremented counter is never tested again")
    }

    /**
     * `counter++` moves the variable on, so the next read of it is of the incremented value.
     *
     * The operator had a box and the box had no consequence: `counter++; int after = counter;` drew
     * `after` taking the value from before the increment, which is a plain arithmetic error sitting
     * in a diagram that otherwise looks right.
     */
    @Test
    fun anIncrementIsTheValueTheVariableHoldsAfterIt() {
        val edges = edgeLabels(buildGraph("unary", listOf("App.java")))
        assertTrue("postInc" to "afterIncrement" in edges, "the increment does not reach the read after it: $edges")
    }

    /**
     * Every arm of a `switch` statement reaches a use below it, and so does falling between them.
     *
     * The fixture's arms are deliberately uneven - one writes a second variable and falls into the
     * next, the default writes both - so that walking them as if they ran in sequence shows up.
     * That is what happened: `out = chosen + side` took the default's 100 and 500 and nothing else,
     * which is a diagram of a `switch` claiming the last arm always runs.
     *
     * `side` is the one that needs the fall-through. `case 3:` is reached either directly, with
     * `side` still 200, or out of the bottom of `case 2:`, which set it to 300, so both have to be
     * there - and a join that took only the falling path would drop the 200 with nothing to show
     * for it.
     */
    @Test
    fun everyArmOfASwitchStatementReachesAUseBelowIt() {
        val graph = buildGraph("switchStatement", listOf("App.java"))
        listOf("10", "30", "100").forEach {
            assertTrue(reaches(graph, it, "out"), "the arm writing $it does not reach 'out'")
        }
        listOf("200", "300", "500").forEach {
            assertTrue(reaches(graph, it, "out"), "the value $it of 'side' does not reach 'out'")
        }
    }

    /**
     * Every value a `switch` expression can produce reaches its result, whichever arm spells it.
     *
     * Java gives an arm three shapes and only one of them worked. An expression body was evaluated;
     * a block body was not walked at all, so `int doubled = bonus * 2;` was code sitting in the
     * corpus that the diagram did not contain, and the `yield` handing it back was replaced by an
     * `UNMODELLED` box standing in for the whole arm. `case 3 -> note - fallback` is here as a
     * second expression arm so the check is about the shape and not about arm order.
     */
    @Test
    fun everyArmOfASwitchExpressionReachesItsResult() {
        val graph = buildGraph("switchExpression", listOf("App.java"))
        assertTrue(reaches(graph, "7", "total"), "the expression arm's value does not reach 'total'")
        assertTrue(reaches(graph, "*", "total"), "the yielded value does not reach 'total'")
        assertTrue(reaches(graph, "-", "total"), "the third arm's value does not reach 'total'")
        assertTrue(reaches(graph, "11", "total"), "the block arm's own computation is not on the page")
        val edges = edgeLabels(graph)
        assertEquals(
            3, edges.count { it == ("kind" to "==") },
            "the selector is not compared against each of the three constant labels: $edges"
        )
    }

    /**
     * An arm that throws is not a value the `switch` can evaluate to.
     *
     * `default -> throw new IllegalStateException(...)` is how most real `switch` expressions spell
     * "no other value is possible", and it was being listed among the alternatives of the result -
     * so the diagram claimed the switch could produce the exception, and `Select.alternatives` is
     * also what passes objects on, so the result was pointed at the exception's fields too. The
     * exception still has to be *drawn*, or this assertion would also pass on an arm that was
     * dropped on the floor, so the pair is checked together.
     */
    @Test
    fun anArmThatThrowsIsNotAValueTheSwitchCanProduce() {
        val graph = buildGraph("switchExpression", listOf("App.java"))
        assertTrue(
            graph.any { it.contains("""["unsupported"]:::LITERAL""") },
            "the throwing arm is not drawn at all, so the negative below proves nothing"
        )
        assertTrue(
            reaches(graph, "\"unsupported\"", "IllegalStateException"),
            "the throwing arm's own operands are not on the page"
        )
        assertFalse(
            reaches(graph, "\"unsupported\"", "total"),
            "the switch is drawn as able to evaluate to a value the throwing arm cannot hand back"
        )
    }

    /**
     * One arm of a `switch` expression does not see what another wrote, because only one of them runs.
     *
     * The same wound as §1's, in the construct where it survived longest: the arms were lowered in
     * sequence from one set of definitions, so `case 3 -> note - fallback` subtracted from the 41
     * that `case 2` assigns. Below the switch both values are right, since either arm may have run -
     * which is the pair that makes this an ordering bug rather than a missing edge.
     */
    @Test
    fun oneArmOfASwitchExpressionDoesNotSeeWhatAnotherWrote() {
        val graph = buildGraph("switchExpression", listOf("App.java"))
        assertTrue(reaches(graph, "0", "-"), "the arm does not read the value from before the switch")
        assertFalse(reaches(graph, "41", "-"), "the arm reads what a different arm wrote")
        assertTrue(reaches(graph, "0", "out"), "the unwritten value of 'note' does not reach below the switch")
        assertTrue(reaches(graph, "41", "out"), "the value 'note' is written in an arm does not reach below it")
    }

    /**
     * A `case` label naming a constant from outside the sources is opaque, not a failure.
     *
     * javac needs the selector's type to work out which constant `case UP` names, so with the enum
     * one module away it answers with a `ClassSymbol` where a field was asked for. Believed, that
     * reached the lowering's local-resolution path, which fails - correctly, for a local - and so a
     * `switch` over an enum from a neighbouring module produced no output for the entire corpus.
     * Pointing codeflow at one module of a multi-module build is the normal way to point it at
     * anything, which is what makes this the common case rather than an exotic one.
     */
    @Test
    fun aCaseLabelFromOutsideTheSourcesIsOpaqueRatherThanAFailure() {
        val graph = buildGraph("externalEnumSwitch", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("UP" to "==" in edges, "the unresolved label of the statement form is not drawn: $edges")
        assertTrue("DOWN" to "==" in edges, "the unresolved label of the expression form is not drawn: $edges")
        assertTrue(reaches(graph, "1", "out"), "the statement form's arm does not reach the use below it")
        assertTrue(reaches(graph, "3", "out"), "the expression form's arm does not reach the use below it")
    }

    /**
     * A constant imported statically from outside the sources is opaque, not a failure.
     *
     * The same wrong-kind answer as the case label, at the commonest site there is: javac reports a
     * name it could not find by handing back a `ClassSymbol`, so a bare identifier came back as kind
     * CLASS where a variable was asked for. Believed, it reached the lowering's local-resolution
     * path, which fails - and rightly, for a local - so one `import static` of a constant declared
     * one module away produced no output for the whole corpus. The gate itself is unchanged: a name
     * javac *did* resolve to a variable, with no definition reaching it, still fails, which is what
     * [aLocalWithNoValueStillFails] holds.
     */
    @Test
    fun aConstantImportedFromOutsideTheSourcesIsOpaqueRatherThanAFailure() {
        val graph = buildGraph("externalConstant", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("MAX_RETRIES" to "budget" in edges, "the constant does not reach the variable it initialises: $edges")
        assertTrue(reaches(graph, "MAX_RETRIES", "spent"), "the constant's value does not flow on to its use")
    }

    /**
     * `boolean.class` names a type in the place a value would go, and so does `String.class`.
     *
     * Whether the receiver of a class literal names a type was asked of what javac resolved it to,
     * and a primitive type name has no `Element` to answer with - so `boolean` fell through to being
     * evaluated as a value, and a type produces none. The reference form always worked, which is what
     * makes the pair the assertion: they are one expression with a different type named in it, and
     * they have to come out as one shape.
     */
    @Test
    fun aClassLiteralNamesATypeWhetherOrNotItIsPrimitive() {
        val graph = buildGraph("classLiteral", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("class" to "primitive" in edges, "the primitive class literal is not drawn: $edges")
        assertTrue("class" to "reference" in edges, "the reference class literal is not drawn: $edges")
    }

    /**
     * A parameter of a class javac could not attribute still resolves to its declaration.
     *
     * `Report extends outside.Base` makes attribution give up on the body but not on the signature,
     * so the parameter's declaration resolved and every read of it did not - one variable recorded
     * under a PARAMETER element and looked up under a null one. The read then failed, and with it the
     * whole corpus, although the definition it wanted was in the same method under a different key.
     * Every exception class whose base class lives in another module has this shape.
     *
     * The whole run throws without the fallback, so any assertion here would do; these two are the
     * ones that say the fallback found the *parameter* rather than something else of that name - the
     * argument at the call site reaching the `super` call through it is what shows that.
     */
    @Test
    fun aParameterOfAnUnattributedClassStillResolvesToItsDeclaration() {
        val graph = buildGraph("unattributedParameter", listOf("App.java", "Report.java"))
        val edges = edgeLabels(graph)
        assertTrue("reason" to "code" in edges, "the parameter does not reach the call reading it: $edges")
        assertTrue(reaches(graph, "LOGGED", "super"), "the argument does not reach the super call through the parameter")
    }

    /**
     * A field inherited from a class outside the corpus is external, not a field nothing declares.
     *
     * The other half of the unattributed-supertype shape. javac reports a member it could not find
     * the same way it reports a *name* it could not find - an `Element` of kind CLASS, typed ERROR -
     * so `this.currency` in a subclass of a class one module over arrived at `unassigned` as a name
     * javac had resolved to something that is not a field, and the run died. The field is real and
     * one module away, which is a limit of the sources and is what `EXTERNAL` says.
     *
     * Two assertions because the receiver decides what flows in, and the second is the one that can
     * fail on a graph that is otherwise complete: drop the receiver and `other` reaches nothing,
     * which is the local the reader would use to tell the two reads apart.
     */
    @Test
    fun aFieldInheritedFromOutsideTheSourcesIsExternalRatherThanAFailure() {
        val graph = buildGraph("inheritedField", listOf("App.java", "Report.java"))
        val edges = edgeLabels(graph)
        assertTrue("code" to "+" in edges, "the inherited field does not reach the concatenation: $edges")
        assertTrue("other" to "code" in edges, "the object the field was read from does not reach it: $edges")
    }

    /**
     * A `try` and its handler are alternatives, so both reach the line after them.
     *
     * A handler runs because the `try` did not finish, which makes this an `if`'s join arrived at
     * from a different direction. Lowered in sequence the handler's write was the only one left
     * standing and `result` was drawn as only ever the fallback - the success path, which is what
     * the code is written for, absent from the diagram of it.
     */
    @Test
    fun aTryAndItsHandlerBothReachAUseAfterThem() {
        val graph = buildGraph("tryCatch", listOf("App.java"))
        assertTrue(reaches(graph, "parseInt", "reported"), "the value from the try does not reach 'reported'")
        assertTrue(reaches(graph, "attempts", "reported"), "the value from the handler does not reach 'reported'")
    }

    /**
     * A field read through a name that can hold either of two objects finds the field on both.
     *
     * The join after an `if` is not only about the value a variable holds, it is about *which object*
     * it is: `chosen` is one of two `Holder`s, so `chosen.amount` is one of two fields. Tracking a
     * single object per variable can only answer with an arm, and the arm it picks is an artefact of
     * the walk rather than of the program - the same wound as a branch drawn straight through, moved
     * into the alias model where it is harder to see.
     */
    @Test
    fun aFieldReadThroughEitherOfTwoObjectsFindsBoth() {
        val graph = buildGraph("aliasBranch", listOf("App.java"))
        assertTrue(reaches(graph, "11", "total"), "the field of the object from one branch does not reach 'total'")
        assertTrue(reaches(graph, "22", "total"), "the field of the object from the other branch does not reach 'total'")
    }

    /**
     * A ternary is a branch written as an expression, so what it produces is either object.
     *
     * The choice is the same one an `if` makes and needs the same answer. Producing no object left
     * the name it was assigned to pointing at a position nothing had written, so the field read
     * through it arrived from nowhere - a box with no edge into it, which reads as a field nobody
     * sets rather than as one this tool lost.
     *
     * Which inputs are the alternatives is the point: `flag` decides and is not one of them, and an
     * array's inputs are its elements, which are not the array.
     */
    @Test
    fun aFieldReadThroughEitherArmOfATernaryFindsBoth() {
        val graph = buildGraph("aliasTernary", listOf("App.java"))
        assertTrue(reaches(graph, "11", "total"), "the field of the object from one arm does not reach 'total'")
        assertTrue(reaches(graph, "22", "total"), "the field of the object from the other arm does not reach 'total'")
    }

    /**
     * A call to a method outside the analysed sources has no body to inline, so it becomes one
     * node that the arguments flow into and the result flows out of. Values still have to be
     * traceable through it.
     */
    @Test
    fun externalCallBecomesOpaqueNode() {
        val edges = edgeLabels(buildGraph("externalCall", listOf("App.java")))
        assertTrue("a" to "abs" in edges, "argument does not reach the external call: $edges")
        assertTrue("abs" to "b" in edges, "external call result does not reach the variable: $edges")
        assertTrue("b" to "println" in edges, "argument does not reach the external call: $edges")
        assertTrue("+" to "c" in edges, "flow does not continue past the external call: $edges")
    }

    /**
     * An object returned by a method outside the analysed sources has no constructor to run, so
     * nothing is known about its memory position. It still has to be usable as a receiver.
     */
    @Test
    fun externalObjectIsUsableAsReceiver() {
        val edges = edgeLabels(buildGraph("externalObject", listOf("App.java")))
        assertTrue("of" to "items" in edges, "external call result does not reach the variable: $edges")
        assertTrue("items" to "size" in edges, "receiver does not reach the call made on it: $edges")
        assertTrue("+" to "doubled" in edges, "flow does not continue past the external object: $edges")
    }

    /** The receiver of a call can be another call, so a value has to stay traceable along a chain. */
    @Test
    fun chainedCallsStayConnected() {
        val edges = edgeLabels(buildGraph("chainedCall", listOf("App.java")))
        assertTrue("items" to "stream" in edges, "receiver does not reach the first call: $edges")
        assertTrue("stream" to "toList" in edges, "first call does not reach the second: $edges")
        assertTrue("toList" to "size" in edges, "second call does not reach the third: $edges")
        assertTrue("size" to "size" in edges, "call result does not reach the variable: $edges")
    }

    /**
     * A unary operator has to become a node of its own. Returning the operand's node instead
     * makes `-value` identical to `value` and `!flag` identical to `flag`, which is not a gap in
     * the graph but a claim that the code does something it does not.
     */
    @Test
    fun unaryOperatorsAreVisibleInTheGraph() {
        val edges = edgeLabels(buildGraph("unary", listOf("App.java")))
        assertTrue("value" to "neg" in edges, "operand does not reach the negation: $edges")
        assertTrue("neg" to "negated" in edges, "negation does not reach the variable: $edges")
        assertTrue("flag" to "not" in edges, "operand does not reach the complement: $edges")
        assertTrue("not" to "inverted" in edges, "complement does not reach the variable: $edges")
        assertTrue("counter" to "postInc" in edges, "operand does not reach the increment: $edges")
    }

    /**
     * An expression codeflow does not model becomes a node saying so, rather than ending the run.
     *
     * One `(int)` cast on a reachable path used to produce zero bytes of output for the entire
     * corpus: `Helper.twice` containing `(int)(v * 2.0)` took down a graph of which it was one node,
     * and a thousand other files went with it.
     *
     * The principle behind the gate is unchanged - a gap must never be drawn as a flow - but there
     * is already an honest rendering for "something here I cannot see inside", and a cast is not
     * more dangerous than `java.util`. So the construct is drawn, labelled with its kind and
     * carrying the line it was written on, with what it was built from flowing in and its value
     * flowing out. It is its own node type, so nothing on the diagram can mistake it for a value
     * codeflow understood.
     */
    @Test
    fun anUnmodelledExpressionBecomesANodeInsteadOfEndingTheRun() {
        val graph = buildGraph("unsupported", listOf("App.java"))
        val types = nodeTypes(graph)
        val edges = edgeLabels(graph)
        assertTrue("TYPE_CAST" to "UNMODELLED" in types, "the cast is not drawn as unmodelled: $types")
        assertTrue("3L" to "TYPE_CAST" in edges, "the operand does not reach the cast: $edges")
        assertTrue("TYPE_CAST" to "count" in edges, "the cast does not reach the variable: $edges")
    }

    /**
     * The same on the right-hand side of an object assignment.
     *
     * That path caught every exception from evaluating the right-hand side and carried on, so an
     * unmodelled construct there did not fail - the variable was simply drawn with nothing flowing
     * into it, which reads as a value that has no source rather than one codeflow could not follow.
     * Object assignment is most of real Java, so this was the gate's largest blind spot, and the
     * node has to arrive on this path rather than the edge being dropped again.
     */
    @Test
    fun anUnmodelledExpressionAssignedToAnObjectIsDrawnToo() {
        val graph = buildGraph("unsupportedAssignment", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("args" to "TYPE_CAST" in edges, "the operand does not reach the cast: $edges")
        assertTrue("TYPE_CAST" to "cast" in edges, "the cast does not reach the variable: $edges")
    }

    /**
     * And for the receiver of a call reaching outside the sources.
     *
     * That receiver was evaluated inside a catch-everything that dropped whatever came back, so the
     * one position where the gate could be reached and ignored was the position it exists for. The
     * result was the opaque call drawn with no input at all: a call that plainly reads a value,
     * drawn as reading nothing.
     */
    @Test
    fun anUnmodelledReceiverStillReachesTheCall() {
        val graph = buildGraph("unmodelledReceiver", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("args" to "TYPE_CAST" in edges, "the operand does not reach the cast: $edges")
        assertTrue("TYPE_CAST" to "toString" in edges, "the cast does not reach the call: $edges")
    }

    /**
     * The entry point can be named, instead of being whichever `main` sorts first.
     *
     * The whole diagram is what one method reaches, so which method that is *is* the diagram. Only
     * `main` could be it, which meant a reader interested in one service method had to find a path
     * to it from an entry point and then look for it among everything else the entry point reaches.
     */
    @Test
    fun theEntryPointCanBeNamedRatherThanBeingWhicheverMainSortsFirst() {
        val graph = buildGraph("funcCall", listOf("App.java"), from = listOf("App#methodB"))
        val labels = nodeTypes(graph).map { it.first }
        val edges = edgeLabels(graph)
        assertTrue(graph.any { it.contains("""subgraph b0["methodB"]""") }, "methodB is not the root: $graph")
        assertTrue("11" to "paramH" in edges, "the chosen method's own body is missing: $edges")
        assertTrue("x" !in labels, "main's body was graphed as well: $labels")
    }

    /**
     * And a corpus with no `main` at all is graphable, which is most Java.
     *
     * Services, controllers and libraries have no entry point of their own, so refusing to start
     * anywhere else excluded most of the tool's own subject matter - including Fineract, its stated
     * real-world target.
     */
    @Test
    fun aCorpusWithNoMainCanStillBeGraphed() {
        val edges = edgeLabels(buildGraph("noMain", listOf("Report.java"), from = listOf("Report#total")))
        assertTrue("base" to "*" in edges, "the parameter does not reach the operator: $edges")
        assertTrue("*" to "bonus" in edges, "the operator does not reach the variable: $edges")
    }

    /**
     * Naming a method that is not there says so, and says what the alternatives were.
     *
     * A typo in a class or method name is the commonest way to get here, and an error that only
     * repeats the name back leaves the reader guessing at spelling, nesting and overloads.
     */
    @Test
    fun anEntryPointThatMatchesNothingNamesTheCandidates() {
        val error = assertFailsWith<GraphException> {
            buildGraph("funcCall", listOf("App.java"), from = listOf("App#methodZ"))
        }
        val message = error.message ?: ""
        assertTrue("App#methodZ" in message, "error does not repeat what was asked for: $message")
        assertTrue("App#methodB" in message, "error does not name a real candidate: $message")
    }

    /**
     * And no `main` with nothing asked for points at the flag rather than at a dead end.
     *
     * This was the whole failure: `No method named 'main'`, and nothing about what to do next.
     */
    private val boundaryFiles = listOf("App.java", "Boundary.java")

    private fun boundaryGraph(boundaries: List<String> = listOf("Boundary")) =
        buildGraph("boundary", boundaryFiles, from = listOf("App#entrypoint"), boundaries = boundaries)

    /**
     * A boundary method's body is not read: every literal it writes is missing with the boundary
     * configured, and present without it - which is what says the test can see a body at all.
     */
    @Test
    fun aBoundaryBodyIsNotRead() {
        val without = nodeTypes(boundaryGraph(emptyList())).map { it.first }
        assertTrue("9001" in without, "the fixture's body literal is not drawn even without a boundary: $without")
        val with = nodeTypes(boundaryGraph()).map { it.first }
        listOf("9001", "9002", "9003").forEach {
            assertTrue(it !in with, "boundary body literal $it was drawn: $with")
        }
    }

    /**
     * Each call is the assumed implementation: parameters into `call <name>`, that straight out
     * through the method's RETURN to the caller - no `result` local in between.
     */
    @Test
    fun aBoundaryCallIsTheAssumedImplementation() {
        val graph = boundaryGraph()
        val types = nodeTypes(graph).toSet()
        assertTrue("call boundaryfunc1" to "EXTERNAL" in types, "no EXTERNAL call node: $types")
        assertTrue(types.none { it.first == "result" }, "a result local is drawn: $types")
        val edges = edgeLabels(graph)
        assertTrue("x" to "call boundaryfunc1" in edges, "the parameter does not feed the call: $edges")
        assertTrue("call boundaryfunc1" to "boundaryfunc1" in edges, "the call does not feed the RETURN: $edges")
    }

    /** What the caller passes reaches the call it is passed to, in each arm of the `if`. */
    @Test
    fun argumentsReachTheBoundaryCallsTheyArePassedTo() {
        val graph = boundaryGraph()
        assertTrue(reaches(graph, "a", "call boundaryfunc1"), "a does not reach call boundaryfunc1")
        assertTrue(reaches(graph, "call boundaryfunc1", "result1"), "the call's result does not reach result1")
        assertTrue(reaches(graph, "result1", "call boundaryfunc2"), "result1 does not reach call boundaryfunc2")
        assertTrue(reaches(graph, "result2", "call boundaryfunc3"), "result2 does not reach call boundaryfunc3")
        assertTrue(reaches(graph, "b", "call boundaryfunc3"), "b does not reach call boundaryfunc3")
        assertTrue(reaches(graph, "c", "call boundaryfunc3"), "c does not reach call boundaryfunc3")
        // The negatives paired with the positives above: `c` is passed to boundaryfunc3 only, and
        // boundaryfunc3 returns nothing. boundaryfunc2 runs after it in the else-arm, which is order
        // and not data - the order chain's edges are ORDER, and a value does not cross them.
        assertFalse(reaches(graph, "c", "call boundaryfunc2"), "c reaches call boundaryfunc2, which it is never passed to")
        assertFalse(reaches(graph, "c", "call boundaryfunc1"), "c reaches call boundaryfunc1, which runs before it is passed anywhere")
    }

    // --- The order boundary calls run in: one `boundaries` token threaded through every call. ---

    private fun blocksUnder(block: GraphBuilderBlock): List<GraphBuilderBlock> =
        listOf(block) + block.calledMethods.flatMap { blocksUnder(it) }

    private fun nodesOf(roots: List<GraphBuilderBlock>): List<GraphNode> =
        roots.flatMap { blocksUnder(it) }.flatMap { it.graph.getNodes() }

    /** Every edge, the entry points' [EdgeKind.EVENT] ones included. */
    private fun allEdgesOf(roots: List<GraphBuilderBlock>): List<Triple<GraphNode, EdgeKind, GraphNode>> =
        nodesOf(roots).flatMap { from -> from.edgesIterator().asSequence().map { Triple(from, it.kind, it.target) }.toList() }

    /** Every edge but an event's: what the code draws, which is what "nothing flows in" asks about. */
    private fun edgesOf(roots: List<GraphBuilderBlock>): List<Triple<GraphNode, EdgeKind, GraphNode>> =
        allEdgesOf(roots).filter { it.second != EdgeKind.EVENT }

    /** The boundary call drawn for the call site on [line] of App.java - one block per call site. */
    private fun callAt(roots: List<GraphBuilderBlock>, line: Int): GraphNode =
        roots.flatMap { blocksUnder(it) }.single { Regex("""App\.java:$line:\d+$""").containsMatchIn(it.openedAt) }
            .graph.getNodes().single { it.getType() == NodeType.EXTERNAL && it.lead == BOUNDARY_CALL_LEAD }

    private fun callNamed(roots: List<GraphBuilderBlock>, label: String): GraphNode =
        nodesOf(roots).single { it.label == label }

    /** The token a call leaves behind: the one `boundaries` box it feeds. */
    private fun orderAfter(roots: List<GraphBuilderBlock>, call: GraphNode): GraphNode =
        edgesOf(roots).filter { it.first === call && it.third.getType() == NodeType.BOUNDARIES }.map { it.third }.single()

    /** The token a call takes: the one `boundaries` box feeding it. */
    private fun orderBefore(roots: List<GraphBuilderBlock>, call: GraphNode): GraphNode =
        edgesOf(roots).filter { it.third === call && it.first.getType() == NodeType.BOUNDARIES }.map { it.first }.single()

    private fun boundaryRootBlocks() =
        rootsOf("boundary", boundaryFiles, from = listOf("App#entrypoint"), boundaries = listOf("Boundary"))

    private fun boundaryOrderRoots(from: List<String> = listOf("App#entrypoint")) =
        rootsOf("boundaryOrder", listOf("App.java", "Gateway.java"), from = from, boundaries = listOf("Gateway"))

    /**
     * The token's splits: a BIN_OP that hands something on along a [EdgeKind.TRUE] or
     * [EdgeKind.FALSE] edge. A join takes its arms on those edges and gives one value out on plain
     * flow, so nothing else in a graph sends them.
     */
    private fun splitsOf(roots: List<GraphBuilderBlock>): List<GraphNode> =
        edgesOf(roots).filter { it.first.getType() == NodeType.BIN_OP && it.second in setOf(EdgeKind.TRUE, EdgeKind.FALSE) }
            .map { it.first }.distinct()

    /** Each edge out of [node], by kind - one target per kind, or the assertion fails. */
    private fun outOf(roots: List<GraphBuilderBlock>, node: GraphNode): Map<EdgeKind, GraphNode> =
        edgesOf(roots).filter { it.first === node }.groupBy { it.second }.mapValues { (_, it) -> it.single().third }

    /** Each edge into [node], by kind - one source per kind, or the assertion fails. */
    private fun into(roots: List<GraphBuilderBlock>, node: GraphNode): Map<EdgeKind, GraphNode> =
        edgesOf(roots).filter { it.third === node }.groupBy { it.second }.mapValues { (_, it) -> it.single().first }

    /**
     * The chain starts at one `boundaries` with nothing flowing in, the first call takes it after
     * its parameter - one input more than it has parameters - and what that call leaves goes on, as
     * its only edge out, into the `if` that splits it: ORDER in beside `a > b`, `true` into the
     * then-arm's first call, `false` into the else-arm's. Neither arm's call takes the token itself.
     */
    @Test
    fun theBoundaryOrderStartsBeforeTheFirstCallAndSplitsAtTheIf() {
        val roots = boundaryRootBlocks()
        val edges = edgesOf(roots)
        val func1 = callAt(roots, 10)
        val start = orderBefore(roots, func1)
        assertEquals(NodeType.BOUNDARIES, start.getType())
        assertTrue(edges.none { it.third === start }, "the start of the chain has something flowing in")
        assertEquals(
            listOf(start), nodesOf(roots).filter { n -> n.getType() == NodeType.BOUNDARIES && edges.none { it.third === n } },
            "the chain does not have exactly one start"
        )
        assertEquals(2, edges.count { it.third === func1 }, "call boundaryfunc1 takes its one parameter and the token, nothing else")
        val after1 = orderAfter(roots, func1)
        assertTrue(after1 !== start, "the call writes back into the box it read")
        val split = edges.single { it.first === after1 }.let { (_, kind, target) ->
            assertEquals(EdgeKind.ORDER, kind, "the token does not go on into the split as order")
            target
        }
        assertEquals("if" to NodeType.BIN_OP, split.label to split.getType(), "the token does not go into an `if`")
        assertEquals(listOf(">"), edges.filter { it.third === split && it.second == EdgeKind.CONDITION }.map { it.first.label },
            "the split is not decided by a > b")
        val then2 = callAt(roots, 13)
        val else3 = callAt(roots, 16)
        assertEquals(mapOf(EdgeKind.TRUE to then2, EdgeKind.FALSE to else3), outOf(roots, split),
            "the split does not hand the token to the then-arm's first call on true and the else-arm's on false")
        for (first in listOf(then2, else3)) {
            assertTrue(edges.none { it.first === after1 && it.third === first }, "${first.label} takes the token without the split")
        }
    }

    /** Each arm runs its two calls in its own order, and neither arm's calls follow the other's. */
    @Test
    fun eachArmRunsItsBoundaryCallsInSourceOrderAndNotTheOther() {
        val roots = boundaryRootBlocks()
        val then2 = callAt(roots, 13)
        val then3 = callAt(roots, 14)
        val else3 = callAt(roots, 16)
        val else2 = callAt(roots, 17)
        assertEquals(listOf("call boundaryfunc2", "call boundaryfunc3", "call boundaryfunc3", "call boundaryfunc2"),
            listOf(then2, then3, else3, else2).map { it.label })
        assertTrue(orderAfter(roots, then2) === orderBefore(roots, then3), "then-arm: 2 does not hand the token to 3")
        assertTrue(orderAfter(roots, else3) === orderBefore(roots, else2), "else-arm: 3 does not hand the token to 2")
        assertTrue(TestFixtures.ordered(then2, then3), "then-arm: call boundaryfunc2 does not run before call boundaryfunc3")
        assertFalse(TestFixtures.ordered(then3, then2), "then-arm: call boundaryfunc3 runs before call boundaryfunc2, the order reversed")
        assertTrue(TestFixtures.ordered(else3, else2), "else-arm: call boundaryfunc3 does not run before call boundaryfunc2")
        assertFalse(TestFixtures.ordered(else2, else3), "else-arm: call boundaryfunc2 runs before call boundaryfunc3, the order reversed")
        for (a in listOf(then2, then3)) for (b in listOf(else3, else2)) {
            assertFalse(TestFixtures.ordered(a, b), "the then-arm's ${a.label} runs before the else-arm's ${b.label}")
            assertFalse(TestFixtures.ordered(b, a), "the else-arm's ${b.label} runs before the then-arm's ${a.label}")
        }
    }

    /** What each arm leaves meets at one `boundaries`, chosen by `a > b` like any static field written in an arm. */
    @Test
    fun theArmsOrdersMeetAtOneGatedJoin() {
        val roots = boundaryRootBlocks()
        val edges = edgesOf(roots)
        val fromThen = orderAfter(roots, callAt(roots, 14))
        val fromElse = orderAfter(roots, callAt(roots, 17))
        val chosen = edges.single { it.first === fromThen }.let { (_, kind, target) ->
            assertEquals(EdgeKind.TRUE, kind, "the then-arm's token does not arrive on the true edge")
            target
        }
        assertEquals(listOf(EdgeKind.FALSE to chosen), edges.filter { it.first === fromElse }.map { it.second to it.third },
            "the else-arm's token does not arrive at the same choice on the false edge")
        assertEquals("if", chosen.label)
        assertEquals(listOf(">"), edges.filter { it.third === chosen && it.second == EdgeKind.CONDITION }.map { it.first.label },
            "the join is not gated by a > b")
        val joined = edges.filter { it.first === chosen }.map { it.third }
        assertEquals(listOf("boundaries entrypoint" to NodeType.BOUNDARIES), joined.map { it.label to it.getType() },
            "the choice does not come out as one boundaries")
        assertEquals(NodeType.BIN_OP, chosen.getType(), "the gate is drawn as the token rather than as the choice it is")
        val splits = splitsOf(roots)
        assertEquals(1, edges.filter { it.first.getType() == NodeType.BOUNDARIES && it.third.label == "if" && it.third !in splits }
            .map { it.third }.distinct().size, "the token is joined at more than one choice")
    }

    /**
     * The token's two edges at each boundary call are [EdgeKind.ORDER], and no other edge is: not the
     * call's value going to `result`, not the join where the arms meet, not the sources' own field
     * called `boundaries` in `boundaryOrder`. A token is a `boundaries` box written in the boundary
     * class; the field's is in App.java. The one other ORDER edge is the token going into the `if`
     * that splits it, whose own edges into each arm's first call are `true` and `false` - so in
     * `boundary` two calls take the token from the split rather than from a `boundaries`.
     */
    @Test
    fun theOrderChainsEdgesAreOrderAndNoOthers() {
        for ((roots, calls, splits) in listOf(Triple(boundaryRootBlocks(), 5, 1), Triple(boundaryOrderRoots(), 4, 0))) {
            val edges = edgesOf(roots)
            fun token(n: GraphNode) = n.getType() == NodeType.BOUNDARIES
            fun call(n: GraphNode) = n.getType() == NodeType.EXTERNAL && n.lead == BOUNDARY_CALL_LEAD
            val chain = edges.filter { (from, _, to) -> (token(from) && call(to)) || (call(from) && token(to)) }
            assertEquals(2 * calls - 2 * splits, chain.size, "not one token in and one out per boundary call: $chain")
            assertEquals(listOf(EdgeKind.ORDER), chain.map { it.second }.distinct(), "a chain edge is not ORDER")
            val others = edges.filter { it !in chain && it.second == EdgeKind.ORDER }
            assertEquals(splitsOf(roots).size, splits, "not as many splits as the fixture has `if`s around boundary calls")
            assertTrue(others.all { token(it.first) && it.third in splitsOf(roots) } && others.size == splits,
                "edges off the chain are ORDER: ${others.map { "${it.first.label} -> ${it.third.label}" }}")
            assertTrue(edges.any { call(it.first) && it.third.getType() == NodeType.RETURN && it.second == EdgeKind.FLOW },
                "the call's value does not reach the method's RETURN as plain flow")
        }
    }

    /**
     * boundaryfunc1 runs before the else-arm's boundaryfunc2, and nothing it is given reaches that
     * call: its parameter's value goes on as `result1`, which only the then-arm uses. Order without
     * data is what ORDER keeps apart - drawn as flow, the parameter would reach every later call.
     */
    @Test
    fun aBoundaryCallRunsBeforeALaterOneItsArgumentsDoNotReach() {
        val roots = boundaryRootBlocks()
        val func1 = callAt(roots, 10)
        val else2 = callAt(roots, 17)
        val then2 = callAt(roots, 13)
        val x = edgesOf(roots).single { it.third === func1 && it.first.getType() == NodeType.FUNC_PARAM }.first
        assertTrue(TestFixtures.ordered(func1, else2), "call boundaryfunc1 does not run before the else-arm's call boundaryfunc2")
        assertFalse(TestFixtures.reaches(x, else2), "boundaryfunc1's argument reaches the else-arm's call boundaryfunc2")
        // The pair: the same argument does reach the then-arm's call, through result1 - real data.
        assertTrue(TestFixtures.reaches(x, then2), "boundaryfunc1's argument does not reach the then-arm's call boundaryfunc2 through result1")
        assertFalse(TestFixtures.ordered(else2, func1), "the else-arm's call boundaryfunc2 runs before call boundaryfunc1")
    }

    private fun boundaryBranchRoots(root: String) =
        rootsOf("boundaryBranch", listOf("App.java", "Port.java"), from = listOf("App#$root"), boundaries = listOf("Port"))

    /**
     * An arm with no Port call in it leaves the token as the split handed it on, so the split's edge
     * for that arm goes straight to the token's join - `if -->|false| if` with no `else` - and the
     * other arm's call leaves its token at the same join on the other edge. The join, not the
     * token from before the `if`, is what `close` takes.
     */
    @Test
    fun anArmWithoutABoundaryCallHandsTheTokenFromTheSplitStraightToTheJoin() {
        for ((root, lines, empty) in listOf(
            Triple("noElse", Triple(20, 22, 24), EdgeKind.FALSE), Triple("onlyElse", Triple(29, 33, 35), EdgeKind.TRUE)
        )) {
            val roots = boundaryBranchRoots(root)
            val (openLine, sendLine, closeLine) = lines
            val full = if (empty == EdgeKind.FALSE) EdgeKind.TRUE else EdgeKind.FALSE
            val split = splitsOf(roots).single()
            val condition = if (root == "noElse") ">" else "<"
            assertEquals(mapOf(EdgeKind.ORDER to orderAfter(roots, callAt(roots, openLine)), EdgeKind.CONDITION to
                    nodesOf(roots).single { it.label == condition }), into(roots, split), "$root: the split's inputs")
            val out = outOf(roots, split)
            val send = callAt(roots, sendLine)
            assertEquals(send, out[full], "$root: the split does not hand the token to send on $full")
            val join = assertNotNull(out[empty], "$root: the split hands nothing on along $empty")
            assertEquals("if" to NodeType.BIN_OP, join.label to join.getType(), "$root: the empty arm's edge does not go to a choice")
            assertTrue(join !in splitsOf(roots), "$root: the empty arm's edge goes to another split")
            assertEquals(mapOf(full to join), outOf(roots, orderAfter(roots, send)),
                "$root: send's token does not arrive at the same join on $full")
            val joined = outOf(roots, join).getValue(EdgeKind.FLOW)
            assertTrue(orderBefore(roots, callAt(roots, closeLine)) === joined, "$root: close does not take the joined token")
        }
    }

    /**
     * An `if` first in the then-arm of another: the outer one splits on `a >= b` and hands the token
     * on `true` into the inner one, which splits it again on `b <= c` - its token comes from the outer
     * split, not from before either `if`. The outer `false` goes to the else-arm's flush.
     */
    @Test
    fun aNestedIfSplitsTheTokenAgainOnItsOwnCondition() {
        val roots = boundaryBranchRoots("nested")
        val outerSplit = splitsOf(roots).single { s -> into(roots, s)[EdgeKind.CONDITION]?.label == ">=" }
        val innerSplit = splitsOf(roots).single { s -> into(roots, s)[EdgeKind.CONDITION]?.label == "<=" }
        assertEquals(2, splitsOf(roots).size, "not one split per `if`")
        assertEquals(orderAfter(roots, callAt(roots, 40)), into(roots, outerSplit)[EdgeKind.ORDER],
            "the outer split does not take open's token")
        assertEquals(mapOf(EdgeKind.TRUE to innerSplit, EdgeKind.FALSE to callAt(roots, 49)), outOf(roots, outerSplit),
            "the outer split does not hand the token to the inner split on true and the else-arm's flush on false")
        assertEquals(setOf(EdgeKind.TRUE, EdgeKind.CONDITION), into(roots, innerSplit).keys,
            "the inner split does not take the token from the outer split's true edge alone")
        assertEquals(mapOf(EdgeKind.TRUE to callAt(roots, 43), EdgeKind.FALSE to callAt(roots, 45)), outOf(roots, innerSplit),
            "the inner split does not hand the token to send on true and flush on false")
    }

    /**
     * Neither arm calls into Port, so nothing splits the token: what `open` leaves goes, as ORDER,
     * straight to `close` past the `if`. The `if` still chooses `r` - its condition goes to that
     * join and nowhere else.
     */
    @Test
    fun anIfWhoseArmsDoNotTouchTheTokenDoesNotSplitIt() {
        val roots = boundaryBranchRoots("untouched")
        val edges = edgesOf(roots)
        val token = orderAfter(roots, callAt(roots, 56))
        assertEquals(mapOf(EdgeKind.ORDER to callAt(roots, 63)), outOf(roots, token), "open's token does not go straight to close")
        val eq = nodesOf(roots).single { it.label == "==" }
        val chosen = edges.filter { it.first === eq && it.second == EdgeKind.CONDITION }.map { it.third }
        assertEquals(1, chosen.size, "a == b decides something besides the join of r: $chosen")
        assertEquals(setOf(EdgeKind.TRUE, EdgeKind.FALSE, EdgeKind.CONDITION),
            edges.filter { it.third === chosen.single() }.map { it.second }.toSet(), "what a == b decides is not r's join")
        assertTrue(edges.none { it.third.label == "if" && it.second == EdgeKind.ORDER }, "the token goes into an `if`")
    }

    /**
     * A source method between two boundary calls - `helper`, calling two more - is inlined, and the
     * chain runs through it in source order: open, fetch, log, close. `log` and `close` are void.
     */
    @Test
    fun oneBoundaryOrderRunsThroughAnInlinedCallee() {
        val roots = boundaryOrderRoots()
        val calls = listOf("call open", "call fetch", "call log", "call close").map { callNamed(roots, it) }
        calls.zipWithNext().forEach { (before, after) ->
            assertTrue(orderAfter(roots, before) === orderBefore(roots, after), "${before.label} does not hand the token to ${after.label}")
        }
        calls.zipWithNext().forEach { (before, after) ->
            assertTrue(TestFixtures.ordered(before, after), "${before.label} does not run before ${after.label}")
            assertFalse(TestFixtures.ordered(after, before), "${after.label} runs before ${before.label}, the order reversed")
        }
    }

    /**
     * `--pure Gateway`: each call is still one `call` box its argument goes into, but none takes or
     * leaves the order token - no `boundaries` box, no ORDER edge. The pair: `--boundary Gateway` on
     * the same fixture has both, so the test fails if `--pure` were read as `--boundary`.
     */
    @Test
    fun aPureCallIsABoundaryCallOutOfTheOrder() {
        val pure = rootsOf("boundaryOrder", listOf("App.java", "Gateway.java"), from = listOf("App#entrypoint"), pures = listOf("Gateway"))
        for (name in listOf("call open", "call fetch", "call log", "call close")) {
            val call = callNamed(pure, name)
            assertEquals(BOUNDARY_CALL_LEAD, call.lead, "$name is not drawn as a boundary call")
            assertTrue(edgesOf(pure).any { it.third === call && it.first.getType() == NodeType.FUNC_PARAM && it.second == EdgeKind.FLOW },
                "$name takes no argument")
        }
        assertTrue(nodesOf(pure).none { it.getType() == NodeType.BOUNDARIES }, "a pure call reads or leaves the token")
        assertTrue(edgesOf(pure).none { it.second == EdgeKind.ORDER }, "a pure call is in the order chain")
        val ordered = boundaryOrderRoots()
        assertTrue(nodesOf(ordered).any { it.getType() == NodeType.BOUNDARIES } && edgesOf(ordered).any { it.second == EdgeKind.ORDER },
            "--boundary on the same fixture has no order chain, so the test above proves nothing")
    }

    /** One class under both flags: whether its calls are ordered is not ours to guess. */
    @Test
    fun aClassBothBoundaryAndPureFails() {
        val error = assertFailsWith<GraphException> {
            rootsOf("boundaryOrder", listOf("App.java", "Gateway.java"), from = listOf("App#entrypoint"),
                boundaries = listOf("Gateway"), pures = listOf("Gateway"))
        }
        assertTrue("Gateway" in error.message!!, "the error does not name the class: ${error.message}")
    }

    /** A void boundary has no result, and still leaves the token for the next call. */
    @Test
    fun aVoidBoundaryCallThreadsTheOrder() {
        val roots = boundaryOrderRoots()
        val log = callNamed(roots, "call log")
        val close = callNamed(roots, "call close")
        assertTrue(orderAfter(roots, log) === orderBefore(roots, close), "the void call log does not hand the token on")
        assertEquals(listOf("boundaries entrypoint"), edgesOf(roots).filter { it.first === close }.map { it.third.label },
            "the last, void, call does not leave the token - or leaves something else")
    }

    /**
     * The sources' own field `boundaries` is not the token: it is told apart by what holds it, not by
     * its name. Its one box takes `a` and gives `seen`, and has no edge to or from the chain.
     */
    @Test
    fun aFieldNamedBoundariesIsNotTheOrderToken() {
        val roots = boundaryOrderRoots()
        val edges = edgesOf(roots)
        val field = nodesOf(roots).filter { it.label == "boundaries" }
        val token = nodesOf(roots).filter { it.getType() == NodeType.BOUNDARIES }
        assertTrue(field.size == 1 && "App.java" in field.single().source, "the field is not one box: $field")
        assertEquals(NodeType.VARIABLE, field.single().getType(), "the program's field is drawn as the token")
        assertTrue(token.size == 5 && token.all { "Gateway.java" in it.source }, "the token is not a start and four writes: $token")
        val box = field.single()
        assertEquals(listOf("a"), edges.filter { it.third === box }.map { it.first.label })
        assertEquals(listOf("seen"), edges.filter { it.first === box }.map { it.third.label })
        assertTrue(edges.none { (it.first === box && it.third in token) || (it.third === box && it.first in token) },
            "an edge joins the program's field to the order chain")
    }

    /**
     * Two entry points each start their own chain, and each start is tied to the other's last call
     * by a SHARED edge, as a static field's unwritten read is: they can run in either order.
     */
    @Test
    fun severalRootsTieTheirOrdersTogetherAsAStaticFieldIs() {
        val roots = boundaryOrderRoots(listOf("App#entrypoint", "App#helper"))
        val edges = edgesOf(roots)
        val (entry, helper) = roots
        fun only(root: GraphBuilderBlock, label: String) = nodesOf(listOf(root)).single { it.label == label }
        val entryStart = orderBefore(listOf(entry), only(entry, "call open"))
        val helperStart = orderBefore(listOf(helper), only(helper, "call fetch"))
        assertTrue(edges.none { it.third === helperStart && it.second == EdgeKind.FLOW }, "the second root's chain continues the first's")
        assertEquals(listOf(EdgeKind.SHARED to orderAfter(listOf(helper), only(helper, "call log"))),
            edges.filter { it.third === entryStart }.map { it.second to it.first })
        assertEquals(listOf(EdgeKind.SHARED to orderAfter(listOf(entry), only(entry, "call close"))),
            edges.filter { it.third === helperStart }.map { it.second to it.first })
        // Two roots, two names: each chain is captioned after the root it was opened from.
        assertEquals(setOf("boundaries entrypoint"), tokensOf(entry).map { it.label }.toSet())
        assertEquals(setOf("boundaries helper"), tokensOf(helper).map { it.label }.toSet())
    }

    private fun tokensOf(root: GraphBuilderBlock): List<GraphNode> =
        nodesOf(listOf(root)).filter { it.getType() == NodeType.BOUNDARIES }

    // --- How the chain and its calls look: BOUNDARIES boxes, `call <name>` with `call` bold. ---

    /**
     * Every box of the token - the start, each write after a call, the join where the arms meet -
     * is BOUNDARIES and captioned after the root, and no other box is BOUNDARIES. A token is found
     * by what it is, its id's name [BOUNDARY_ORDER] (the gate of its join is `if boundaries`, a
     * BIN_OP), so a wrong caption cannot hide one from the check.
     */
    @Test
    fun everyOrderTokenIsBoundariesCaptionedAfterItsRoot() {
        val nodes = nodesOf(boundaryRootBlocks())
        val (tokens, others) = nodes.partition { it.id.label == BOUNDARY_ORDER }
        assertEquals(listOf(NodeType.BIN_OP), others.filter { it.id.label == "if $BOUNDARY_ORDER" }.map { it.getType() },
            "the join is not gated by one if")
        assertEquals(7, tokens.size, "not a start, five writes and a join: ${tokens.map { it.label }}")
        assertEquals(setOf("boundaries entrypoint" to NodeType.BOUNDARIES), tokens.map { it.label to it.getType() }.toSet())
        assertTrue(others.none { it.getType() == NodeType.BOUNDARIES }, "a box that is not the token is BOUNDARIES")
    }

    /**
     * Each boundary call is `call <name>` with `call` as its lead; no other box has a lead. The
     * `boundaryRoots` fixture's `later.call()` is an outside call labelled `call` that is no
     * boundary: emphasis read off the text would make it bold.
     */
    @Test
    fun eachBoundaryCallIsCallNameAndOnlyItsCallIsBold() {
        val leading = nodesOf(boundaryRootBlocks()).filter { it.lead != null }
        assertEquals(
            listOf("call boundaryfunc1", "call boundaryfunc2", "call boundaryfunc2", "call boundaryfunc3", "call boundaryfunc3"),
            leading.map { it.label }.sorted()
        )
        assertTrue(leading.all { it.lead == "call" && it.getType() == NodeType.EXTERNAL }, "a lead is not call on an EXTERNAL")
        val plain = nodesOf(boundaryRootsFixture()).filter { it.label == "call" }
        assertEquals(listOf(NodeType.EXTERNAL to null), plain.map { it.getType() to it.lead },
            "the outside call named call is missing, or bold")
    }

    /**
     * A callee inlined between two boundary calls - `helper` - leaves tokens of the root's chain,
     * captioned `boundaries entrypoint`, not after the method its frame runs.
     */
    @Test
    fun anInlinedCalleesTokenIsCaptionedAfterTheRoot() {
        val roots = boundaryOrderRoots()
        val helper = roots.flatMap { blocksUnder(it) }.single { it.getMethodName() == "helper" }
        val inHelper = tokensOf(helper)
        assertTrue(inHelper.size >= 2, "helper's boundary calls leave no token: $inHelper")
        assertEquals(setOf("boundaries entrypoint"), roots.flatMap { tokensOf(it) }.map { it.label }.toSet())
    }

    /** `boundaryRoots/`: two roots calling one boundary class, as `--from App#first --from App#second`. */
    private fun boundaryRootsFixture(boundaries: List<String> = listOf("Store")) = rootsOf(
        "boundaryRoots", listOf("App.java", "Store.java"),
        from = listOf("App#first", "App#second"), boundaries = boundaries
    )

    private fun boundaryCalls(root: GraphBuilderBlock) = nodesOf(listOf(root)).filter { it.lead == BOUNDARY_CALL_LEAD }

    /** Each root's chain is captioned after that root, and only that root. */
    @Test
    fun eachRootsChainIsCaptionedAfterItsRoot() {
        val (first, second) = boundaryRootsFixture()
        assertEquals(setOf("boundaries first"), tokensOf(first).map { it.label }.toSet())
        assertEquals(setOf("boundaries second"), tokensOf(second).map { it.label }.toSet())
        assertTrue(tokensOf(first).size == 3 && tokensOf(second).size == 2, "not a start and a write per call per root")
    }

    /** Each root draws its own boundary call box per call site; no box is shared between roots. */
    @Test
    fun eachRootHasItsOwnBoundaryCallPerCallSite() {
        val (first, second) = boundaryRootsFixture()
        val (save, load) = boundaryCalls(first)
        assertEquals(listOf("call save", "call load"), listOf(save, load).map { it.label })
        assertEquals(listOf("call save"), boundaryCalls(second).map { it.label })
        assertTrue(boundaryCalls(first).none { it in boundaryCalls(second) }, "a call box is drawn in both roots")
        assertTrue(TestFixtures.ordered(save, load), "first: save does not run before load")
        assertFalse(TestFixtures.ordered(load, save), "first: load runs before save, the order reversed")
    }

    /** What a root is passed reaches its own boundary calls and never the other root's. */
    @Test
    fun eachRootsArgumentsReachOnlyItsOwnCalls() {
        val (first, second) = boundaryRootsFixture()
        val a = first.parameterNodes.single()
        val b = second.parameterNodes.first()
        boundaryCalls(first).forEach { assertTrue(TestFixtures.reaches(a, it), "a does not reach first's ${it.label}") }
        boundaryCalls(second).forEach { assertTrue(TestFixtures.reaches(b, it), "b does not reach second's ${it.label}") }
        boundaryCalls(second).forEach { assertFalse(TestFixtures.reaches(a, it), "a reaches second's ${it.label}") }
        boundaryCalls(first).forEach { assertFalse(TestFixtures.reaches(b, it), "b reaches first's ${it.label}") }
    }

    /**
     * The two chains are tied by SHARED edges only - each start takes the other root's last write,
     * as a static's unwritten read does - and no ORDER edge, nor any other, crosses between them.
     */
    @Test
    fun twoRootsChainsAreTiedOnlyBySharedEdges() {
        val roots = boundaryRootsFixture()
        val (first, second) = roots
        val edges = edgesOf(roots)
        val inFirst = nodesOf(listOf(first)).toSet()
        val crossing = edges.filter { (it.first in inFirst) != (it.third in inFirst) }
        assertEquals(listOf(EdgeKind.SHARED, EdgeKind.SHARED), crossing.map { it.second }, "edges cross between roots: $crossing")
        fun start(root: GraphBuilderBlock) = tokensOf(root).single { t -> edges.none { it.third === t && it.second != EdgeKind.SHARED } }
        fun last(root: GraphBuilderBlock) = tokensOf(root).single { t -> edges.none { it.first === t && it.second != EdgeKind.SHARED } }
        assertEquals(
            setOf(last(first) to start(second), last(second) to start(first)),
            crossing.map { it.first to it.third }.toSet(), "a SHARED edge is not last write to the other root's start"
        )
    }

    // --- The entry event: one per root, starting what nothing else feeds. ---

    /**
     * `boundary/`'s one root has one EVENT, `event entrypoint`, its lowest serial. Every other node
     * nothing else feeds has exactly one EVENT edge in, from it; no node something else feeds has one.
     * The `boundaries` chain start is among what it starts.
     */
    @Test
    fun theEntryEventStartsEveryNodeNothingElseFeeds() {
        val roots = boundaryRootBlocks()
        val edges = allEdgesOf(roots)
        val nodes = nodesOf(roots)
        val events = nodes.filter { it.getType() == NodeType.EVENT }
        assertEquals(listOf("event entrypoint"), events.map { it.label })
        val event = events.single()
        assertEquals(nodes.minOf { it.serial }, event.serial, "the event is not the root's first node")
        val fed = edges.filter { it.second != EdgeKind.EVENT }.map { it.third }.toSet()
        for (node in nodes) {
            if (node == event) continue
            val starts = edges.filter { it.third == node && it.second == EdgeKind.EVENT }.map { it.first }
            if (node in fed) assertEquals(emptyList(), starts, "${node.label} is fed and still gets an event edge")
            else assertEquals(listOf(event), starts, "${node.label} is fed by nothing and not by exactly the event")
        }
        assertTrue(edges.none { it.first == event && it.second != EdgeKind.EVENT }, "the event has a non-EVENT edge")
        val start = orderBefore(roots, callAt(roots, 10))
        assertTrue(edges.any { it.first == event && it.third == start }, "the boundaries chain start is not started by the event")
    }

    /**
     * `boundaryRoots/`: two roots, two events, each starting only its own root's nodes. A read that
     * gets a SHARED edge from the other root still has its event edge: "nothing feeds it" is judged
     * within the entry point, since the other one may not have run.
     */
    @Test
    fun eachRootsEventStartsOnlyItsOwnNodesSharedReadsIncluded() {
        val roots = boundaryRootsFixture()
        val edges = allEdgesOf(roots)
        assertEquals(
            listOf(listOf("event first"), listOf("event second")),
            roots.map { root -> nodesOf(listOf(root)).filter { it.getType() == NodeType.EVENT }.map { it.label } }
        )
        for (root in roots) {
            val event = nodesOf(listOf(root)).single { it.getType() == NodeType.EVENT }
            val own = nodesOf(listOf(root)).toSet()
            val starts = edges.filter { it.first == event }.map { it.third }
            assertTrue(starts.isNotEmpty(), "${event.label} starts nothing")
            assertTrue(starts.all { it in own }, "${event.label} starts another root's node")
        }
        val sharedReads = edges.filter { it.second == EdgeKind.SHARED }.map { it.third }
        assertEquals(2, sharedReads.size, "not one SHARED read per root")
        sharedReads.forEach { read ->
            assertEquals(1, edges.count { it.third == read && it.second == EdgeKind.EVENT }, "the SHARED-fed ${read.label} has no event edge")
        }
    }

    /** Store's bodies are never read, by either root - and are, without the boundary. */
    @Test
    fun neitherRootReadsTheBoundaryBodies() {
        val labels = nodesOf(boundaryRootsFixture()).map { it.label }
        assertTrue(labels.none { it == "8001" || it == "8002" }, "a boundary body literal was drawn: $labels")
        val read = nodesOf(boundaryRootsFixture(emptyList())).map { it.label }
        assertTrue("8001" in read && "8002" in read, "the body literals are not drawn even without --boundary: $read")
    }

    // --- A boundary that is an interface, reached through an injected field: `boundaryInterface/`. ---

    private val boundaryInterfaceFiles = listOf("Service.java", "Store.java", "StoreImpl.java")

    /** `run` calls Store through a field nobody `new`ed; `known` through a local that is a `new StoreImpl()`. */
    private fun boundaryInterfaceRoots(boundaries: List<String> = listOf("Store")) = rootsOf(
        "boundaryInterface", boundaryInterfaceFiles, from = listOf("Service#run", "Service#known"), boundaries = boundaries
    )

    /**
     * An interface's methods have no body, and on a boundary that is no obstacle: `store.save(a)`
     * draws `call save` with `a` going in, then the token, `ORDER` both ways, into `call load`.
     */
    @Test
    fun anInterfaceBoundaryDrawsItsCallsInOrder() {
        val roots = boundaryInterfaceRoots()
        val run = roots.first()
        val (save, load) = boundaryCalls(run).also {
            assertEquals(listOf("call save", "call load"), it.map { call -> call.label })
        }
        val a = run.parameterNodes.single()
        assertTrue(TestFixtures.reaches(a, save), "a does not reach call save")
        assertFalse(TestFixtures.reaches(a, load), "a reaches call load, which it is never passed to")
        val token = orderAfter(roots, save)
        val edges = edgesOf(roots)
        assertTrue(Triple(save, EdgeKind.ORDER, token) in edges, "call save does not leave the token as ORDER")
        assertTrue(Triple(token, EdgeKind.ORDER, load) in edges, "call load does not take save's token as ORDER")
        assertEquals(listOf(true, true), run.calledMethods.map { it.boundary }, "save and load's blocks are not boundary blocks")
    }

    /**
     * No dispatch past a boundary: where the receiver is known to be a `new StoreImpl()`, the call
     * is still the boundary, and StoreImpl's bodies are drawn nowhere. Without `--boundary` they are
     * - dispatch on the object, as ever.
     */
    @Test
    fun aBoundaryIsNotDispatchedPastToItsImplementation() {
        val roots = boundaryInterfaceRoots()
        val labels = nodesOf(roots).map { it.label }
        assertTrue(labels.none { it == "7001" || it == "7002" }, "an implementation body was drawn: $labels")
        assertEquals(listOf("call save", "call load"), boundaryCalls(roots.last()).map { it.label })
        val read = nodesOf(boundaryInterfaceRoots(emptyList())).map { it.label }
        assertTrue("7001" in read && "7002" in read, "the known receiver does not reach StoreImpl without --boundary: $read")
    }

    /**
     * Without `--boundary` an interface method stays unregistered: `store.save(a)` is today's bare
     * outside call - an EXTERNAL `save`, no block opened, nothing bold.
     */
    @Test
    fun withoutTheBoundaryAnInterfaceCallIsABareExternal() {
        val run = boundaryInterfaceRoots(emptyList()).first()
        assertEquals(emptyList(), run.calledMethods.map { it.getMethodName() }, "a block was opened for a bodyless method")
        val externals = run.graph.getNodes().filter { it.getType() == NodeType.EXTERNAL }
        assertEquals(listOf("save" to null, "load" to null), externals.map { it.label to it.lead })
        assertTrue(TestFixtures.reaches(run.parameterNodes.single(), externals.first()), "a does not reach save")
    }

    /**
     * The summarizer agrees: `store.save(a)` on a field's object, overridden in the sources, is the
     * boundary call and not an undecided dispatch - no `dispatch` gap, and `a` goes into `call save`.
     */
    @Test
    fun summariesDoNotDispatchPastAnInterfaceBoundary() {
        val doc = buildSummaries("boundaryInterface", listOf("Service#run"), listOf("Store"))
        val run = summaryRows(doc).single()
        assertEquals(0, run.getAsJsonArray("gaps").size(), "a gap on a boundary call: ${run.getAsJsonArray("gaps")}")
        val flows = flowsOf(doc, "boundaryInterface.Service#run(int)")
        assertTrue(flows.any { it.startsWith("P0>ext-arg:call save@") }, "a does not go into call save: $flows")
    }

    /** The payload marks an interface boundary's block as it marks a class's: what the condensed view groups by. */
    @Test
    fun jsonMarksAnInterfaceBoundarysBlocks() {
        val boxes = jsonNodes(jsonOf(boundaryInterfaceRoots())).filter { it.get("type").asString == "METHOD" }
        val saves = boxes.filter { jsonLabel(it) == "save" }
        assertEquals(2, saves.size, "not one save block per root: ${saves.map { it.get("method") }}")
        saves.forEach {
            assertEquals("boundaryInterface.Store#save(int)", it.get("method").asString)
            assertEquals(true, it.get("boundary")?.asBoolean, "Store#save's block is not marked a boundary")
        }
    }

    // --- Arguments files: `@path` is replaced by the arguments the file holds. ---

    private fun cli(vararg argv: String): String {
        val out = java.io.ByteArrayOutputStream()
        val saved = System.out
        System.setOut(java.io.PrintStream(out, true))
        try {
            assertEquals(0, runCli(arrayOf(*argv)))
        } finally {
            System.setOut(saved)
        }
        return out.toString()
    }

    /**
     * A file of roots and boundaries gives the document the same arguments inline do. It leads with
     * a blank line, ahead of the directory - taken as an argument, that would be the directory - and
     * has a comment that would fail as a `--boundary` naming nothing if it were read.
     */
    @Test
    fun anArgumentsFileIsTheSameAsItsArgumentsInline() {
        val file = Files.createTempFile("codeflow", ".args")
        try {
            Files.writeString(
                file,
                """
                |
                |# --boundary Nowhere
                |--from Service#run --from Service#known
                |   # indented comment
                |
                |--boundary Store
                |""".trimMargin()
            )
            val dir = testResourcesPath.resolve("boundaryInterface").toString()
            val inline = cli(dir, "--from", "Service#run", "--from", "Service#known", "--boundary", "Store", "--json")
            assertEquals(inline, cli("@$file", dir, "--json"))
            assertTrue("\"boundary\": true" in inline, "the inline run drew no boundary: $inline")
        } finally {
            Files.delete(file)
        }
    }

    @Test
    fun aMissingArgumentsFileFailsNamingIt() {
        val error = assertFailsWith<IllegalArgumentException> { runCli(arrayOf("@/nowhere/roots.args", "src")) }
        assertTrue("/nowhere/roots.args" in (error.message ?: ""), "the error does not name the file: ${error.message}")
    }

    @Test
    fun aBoundaryThatNamesNoClassFailsLoudly() {
        val error = assertFailsWith<GraphException> { boundaryGraph(listOf("Nowhere")) }
        val message = error.message ?: ""
        assertTrue("Nowhere" in message, "error does not repeat what was asked for: $message")
        assertTrue("boundary.Boundary" in message, "error does not name a real candidate: $message")
    }

    /** The summarizer reads the same lowered body, so a boundary summarises as one opaque call. */
    @Test
    fun aBoundarySummarisesAsItsAssumedImplementation() {
        val doc = buildSummaries("boundary", boundaries = listOf("Boundary"))
        val flows = flowsOf(doc, "boundary.Boundary#boundaryfunc2(int,int)")
        val ext = Regex("""ext:call boundaryfunc2@[\w/]*Boundary\.java:\d+:\d+>RET""")
        assertTrue(flows.any { it.startsWith("P0>ext-arg:call boundaryfunc2@") }, "P0 does not reach the call: $flows")
        assertTrue(flows.any { it.startsWith("P1>ext-arg:call boundaryfunc2@") }, "P1 does not reach the call: $flows")
        assertTrue(flows.any { ext.matches(it) }, "the call does not reach RET: $flows")
    }

    /** `--boundary` is a known flag, and what it hides is hidden on stdout too. */
    @Test
    fun boundaryIsAKnownFlag() {
        val out = java.io.ByteArrayOutputStream()
        val saved = System.out
        System.setOut(java.io.PrintStream(out, true))
        val status = try {
            runCli(arrayOf(testResourcesPath.resolve("boundary").toString(), "--from", "App#entrypoint", "--boundary", "Boundary"))
        } finally {
            System.setOut(saved)
        }
        assertEquals(0, status)
        assertTrue("[\"`**call** boundaryfunc1`\"]:::EXTERNAL" in out.toString(), "the call is not drawn, with call in bold: $out")
        assertTrue("9001" !in out.toString(), "the boundary body was drawn: $out")
    }

    @Test
    fun noMainAndNoChoiceSaysHowToChoose() {
        val error = assertFailsWith<GraphException> { buildGraph("noMain", listOf("Report.java")) }
        val message = error.message ?: ""
        assertTrue("--from" in message, "error does not name the flag: $message")
        assertTrue("Report#total" in message, "error does not name a candidate: $message")
    }

    /**
     * The run says what it could not model, so a reader is told rather than left to notice.
     *
     * The node on the diagram is not enough on its own: nobody opens a graph of a thousand nodes
     * looking for the handful that are gaps. This is also what the exit status is taken from, which
     * is the only part of it a build can act on.
     *
     * Once per construct, not once per call site. A method is inlined at every call, so one cast in
     * a helper called from twenty places would otherwise be reported twenty times - a count nobody
     * could reconcile with the source.
     */
    @Test
    fun theRunReportsEachConstructItCouldNotModelOnce() {
        val testDirPath = testResourcesPath.resolve("unsupported")
        val reader = AstReader(testResourcesPath)
        reader.process(listOf(testDirPath.resolve("App.java")))
        assertEquals(listOf("TYPE_CAST at unsupported/App.java:15:21"), reader.unmodelled)
    }

    /**
     * `--summaries` reports what it could not model the way the graph run does, and from the same
     * list, so the exit status `main` takes from [AstReader.unmodelled] is non-zero for it too. The
     * summarizer never draws, so a construct only the builder recorded was a gap in the document
     * and a run that exited 0.
     */
    @Test
    fun summariesReportEachConstructTheyCouldNotModel() {
        val reader = AstReader(testResourcesPath)
        val summaries = reader.summarise(listOf(testResourcesPath.resolve("unsupported").resolve("App.java")))
        assertEquals(listOf("TYPE_CAST at unsupported/App.java:15:21"), reader.unmodelled)
        assertTrue(summaries.any { (_, s) -> s.gaps.any { it.kind == "unmodelled" && it.detail == "TYPE_CAST" } },
            "the cast is not a gap in the document")
    }

    /** And says nothing when there was nothing to say, so the summary means something. */
    @Test
    fun aRunThatModelledEverythingReportsNothing() {
        val testDirPath = testResourcesPath.resolve("base")
        val reader = AstReader(testResourcesPath)
        reader.process(listOf(testDirPath.resolve("App.java")))
        assertTrue(reader.unmodelled.isEmpty(), "reported a gap where there is none: ${reader.unmodelled}")
    }

    /**
     * The node carries the construct's own line, not the enclosing statement's.
     *
     * A reader who sees `TYPE_CAST` on the diagram has one question, and it is where to look. The
     * label alone names the kind, which on a file with several casts narrows nothing.
     */
    @Test
    fun anUnmodelledNodeSaysWhereTheConstructWas() {
        val cast = jsonNodes(buildJson("unsupported", listOf("App.java")))
            .single { it.get("type").asString == "UNMODELLED" }
        assertEquals("TYPE_CAST", jsonLabel(cast))
        assertTrue(
            jsonSource(cast)?.startsWith("unsupported/App.java:15:") == true,
            "the cast on line 15 does not say so: ${jsonSource(cast)}"
        )
    }

    /**
     * `new X(...)` is a value, and the variable it is assigned to has to receive it.
     *
     * It was not modelled as one: the constructor was inlined as a side effect of working out the
     * memory position, and nothing produced a node for the object. In an argument position that
     * failed outright; in an assignment position the failure was swallowed, so the variable was
     * simply drawn with nothing flowing into it and the diagram read as if the object came from
     * nowhere. That is on nearly every line of real Java.
     */
    @Test
    fun constructedObjectReachesTheVariableItIsAssignedTo() {
        val edges = edgeLabels(buildGraph("newObject", listOf("App.java")))
        assertTrue("seed" to "v" in edges, "argument does not reach the constructor parameter: $edges")
        assertTrue("<init>" to "box" in edges, "the constructed object does not reach the variable: $edges")
        assertTrue("\"text\"" to "StringBuilder" in edges, "argument does not reach the opaque construction: $edges")
        assertTrue("StringBuilder" to "sb" in edges, "the opaque construction does not reach the variable: $edges")
    }

    /**
     * A method on a nested class is code in the analysed sources and has to be inlined like any
     * other. Only the top level was walked, so every nested and inner class came out as the opaque
     * external node - a box labelled with the method name and nothing inside it, indistinguishable
     * on the diagram from a call into the standard library.
     */
    @Test
    fun aMethodOnANestedClassIsInlinedLikeAnyOther() {
        val edges = edgeLabels(buildGraph("nestedClass", listOf("App.java")))
        assertTrue("seed" to "v" in edges, "argument does not reach the parameter: $edges")
        assertTrue("v" to "+" in edges, "the nested class's body was not inlined: $edges")
        assertTrue("+" to "twice" in edges, "the nested class's body does not reach its return: $edges")
        assertTrue("twice" to "doubled" in edges, "the return does not reach the variable: $edges")
    }

    /**
     * `this` passed as an argument is a value like any other, and it is the object the method is
     * running on - so what the callee reads off it has to be that object's fields.
     *
     * It had no node at all: `this` was handled when working out a memory position but not when
     * evaluating, so a bare `this` was a name that resolved to nothing and took the method down.
     * A builder handing itself to a constructor is the ordinary case.
     */
    @Test
    fun thisIsAValueCarryingTheObjectItRefersTo() {
        val graph = buildGraph("thisReference", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("this" to "origin" in edges, "`this` does not reach the parameter it is passed to: $edges")
        assertTrue("value" to "held" in edges, "the field read through `this` is not the object's own: $edges")
        assertTrue(reaches(graph, "7", "out"), "the value does not survive the round trip through `this`: $graph")
    }

    /**
     * An object passed to a method is the same object inside it, so a field read off the parameter
     * has to find the field the caller's object holds.
     *
     * Only the nodes were connected, never the memory positions, so the parameter named an object
     * nothing was known about and `origin.value` took the opaque path: a node labelled `value`,
     * of the type that means "outside the analysed sources", with no edge to the field really
     * holding the value. The diagram was complete and readable and the flow it drew was false.
     */
    @Test
    fun anObjectArgumentIsTheSameObjectInsideTheMethod() {
        val graph = buildGraph("objectArgument", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("seed" to "value" in edges, "the constructor does not fill the field: $edges")
        assertTrue("value" to "read" in edges, "the field read off the parameter is not the object's own: $edges")
        assertTrue(reaches(graph, "7", "out"), "the value does not survive being passed as an object: $graph")
    }

    /**
     * The object a factory method returns is the object it constructed, so a method inlined on it
     * afterwards reads that object's fields.
     *
     * The result of a call was given a memory position of its own, holding nothing. That is not a
     * harmless approximation: inlining a method against it means the body's own field reads resolve
     * to nothing, so `Money.of(...)` followed by `.getAmount()` - a factory then a getter, which is
     * most of a real codebase - took the whole run down.
     */
    @Test
    fun theObjectAMethodReturnsKeepsItsIdentity() {
        val graph = buildGraph("returnedObject", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("seed" to "held" in edges, "the constructor does not fill the field: $edges")
        assertTrue("held" to "read" in edges, "the getter does not read the constructed object's field: $edges")
        assertTrue(reaches(graph, "3", "out"), "the value does not survive the factory and the getter: $graph")
    }

    /**
     * Every argument past the last declared parameter flows into the varargs one.
     *
     * They all end up in the array it names, so they all reach it. Indexing straight into the
     * parameter list walked off the end instead, and an IndexOutOfBoundsException names no source
     * at all - `String.format(fmt, x, y)` against an in-source method is enough to reach it.
     */
    @Test
    fun everyArgumentPastTheLastParameterReachesTheVarargsOne() {
        val graph = buildGraph("varargs", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("1" to "base" in edges, "the fixed argument does not reach its parameter: $edges")
        assertTrue("2" to "rest" in edges, "the first variadic argument does not reach the array: $edges")
        assertTrue("3" to "rest" in edges, "the second variadic argument does not reach the array: $edges")
        assertTrue(reaches(graph, "3", "out"), "a variadic value does not survive the call: $graph")
    }

    /**
     * A bare `return;` carries no value, and does not stop the rest of the method being graphed.
     *
     * Every return was assumed to have a value, so an early exit - the ordinary guard clause at the
     * top of a method - came out as a NullPointerException with no file and no line. That is worse
     * to be handed than a wrong graph: there is nothing in it to look at.
     */
    @Test
    fun aReturnWithNoValueCarriesNone() {
        val graph = buildGraph("voidReturn", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("seed" to "held" in edges, "the method past the early exit was not graphed: $edges")
        assertTrue(reaches(graph, "5", "out"), "the value does not survive the call: $graph")
        assertTrue(edges.none { it.second == "store" }, "the valueless return was wired up: $edges")
    }

    /**
     * `names::size` is a value, and the object it is bound to flows into it.
     *
     * Nothing here calls it, so the method it names has no arguments to bind and no call site to be
     * inlined under - it is opaque, like a call outside the sources. What it captures is not: the
     * receiver is a real value the function holds on to, and dropping that edge would break the
     * chain through every stream pipeline in a modern codebase.
     */
    @Test
    fun aMethodReferenceIsAValueCarryingWhatItCaptures() {
        val graph = buildGraph("memberReference", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("names" to "size" in edges, "the captured receiver does not reach the reference: $edges")
        assertTrue("size" to "counter" in edges, "the reference does not reach the variable: $edges")
        assertTrue("size" to "EXTERNAL" in nodeTypes(graph), "the reference is not opaque: ${nodeTypes(graph)}")
    }

    /**
     * A call through an interface reaches the implementation its receiver was constructed as.
     *
     * This was the fixture that asserted the opposite: a declaration with no body was left
     * unregistered, so the call went opaque rather than guessing which implementation it reached.
     * The refusal was right and the reason it gave was wrong - which implementation a call reaches
     * is decided by the receiver's class, and the receiver's class is *known* here, because
     * `new Doubling()` is on the page two lines up.
     *
     * What is still refused is a receiver that says nothing: no tracked object means no dispatch,
     * and the opaque path is what that draws.
     */
    @Test
    fun aCallThroughAnInterfaceReachesTheImplementationItsReceiverHas() {
        val graph = buildGraph("abstractMethod", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertFalse("read" to "EXTERNAL" in nodeTypes(graph), "the interface call is still opaque: ${nodeTypes(graph)}")
        assertTrue(reaches(graph, "3", "viaInterface"), "the interface call drops its argument: $graph")
        assertTrue(reaches(graph, "4", "viaClass"), "the value does not survive the direct call: $graph")
        // One per call site: the body is inlined at each, so `Doubling.read` is drawn twice.
        assertEquals(2, edges.count { it == "+" to "read" }, "both calls should inline the same body: $edges")
    }

    /**
     * A call reaches the implementation the receiver's object has, not the one its declared type
     * names.
     *
     * `Base b = new Sub(); b.f(7)` resolved to `Base.f`, which is what javac answers about the
     * declared type, and codeflow inlined it: `out` received `7 + 1` for a program returning 700.
     * No EXTERNAL node and no warning - the wrong body drawn with the same confidence as a right
     * one, which is the failure the whole project is organised against.
     *
     * The object is what decides, and it was already known here: `b` carries the MemPos that
     * `new Sub()` created, and inlining is per call site, so nothing had to be invented to ask.
     */
    @Test
    fun aCallReachesTheOverrideTheReceiverActuallyHas() {
        val graph = buildGraph("overriddenMethod", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("100" to "*" in edges, "the override's body is not drawn: $edges")
        assertTrue(reaches(graph, "7", "out"), "the argument does not reach the result: $graph")
        assertFalse("1" to "+" in edges, "the superclass body was inlined instead: $edges")
    }

    /**
     * `super.f(...)` runs the implementation the written class names, not the one the object is.
     *
     * The receiver of a `super` call is the same object as `this`, so dispatching on the object
     * sends it back to the method it is written inside. The lowering used to collapse `this` and
     * `super` into one receiver, which was right until the object started deciding anything.
     */
    @Test
    fun aSuperCallDoesNotDispatchBackToTheOverride() {
        val graph = buildGraph("overriddenSuper", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("1" to "+" in edges, "the superclass body is not drawn: $edges")
        assertTrue("100" to "*" in edges, "the override's own body is not drawn: $edges")
        assertFalse("f" to "EXTERNAL" in nodeTypes(graph), "the super call went opaque: ${nodeTypes(graph)}")
    }

    /**
     * An unqualified call inside a superclass method reaches the subclass's override.
     *
     * `step(x)` in `Base.template` names no receiver, so it runs on the object `template` was
     * entered on. One object is one MemPos across the whole inheritance chain - `construct` makes
     * one and `delegate` runs the superclass constructors on it - so the position says `Sub` even
     * while a method of `Base` is running on it. Without that, a template method is drawn as
     * though the hook were never overridden.
     */
    @Test
    fun anUnqualifiedCallInASuperclassReachesTheOverride() {
        val graph = buildGraph("templateMethod", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("100" to "*" in edges, "the override is not reached through `this`: $edges")
        assertTrue(reaches(graph, "7", "out"), "the argument does not reach the result: $graph")
    }

    /**
     * A node says where in the source it came from.
     *
     * "Which line is this?" is the question a reader of unfamiliar code asks constantly, and nothing
     * carried a position past the builder, so no exporter and no viewer could answer it. codemap
     * tags every node with its line and asserts it in the goldens; this is that, arrived at from the
     * other direction.
     *
     * The line is pinned and the column is not. The line is the behaviour - it is what a reader
     * navigates by - and the column moves whenever the fixture is reindented, which would make this
     * fail for a reason that has nothing to do with what it tests.
     */
    @Test
    fun aNodeCarriesTheSourceLineItWasWrittenOn() {
        val nodes = jsonNodes(buildJson("base", listOf("App.java")))
        val literal = nodes.single { jsonLabel(it) == "5" }
        val source = jsonSource(literal)
        assertTrue(
            source != null && source.startsWith("base/App.java:8:"),
            "the literal on line 8 does not say so: $source"
        )
    }

    /**
     * Every node, not merely the ones that were easy.
     *
     * A position on most nodes is worse than none on any: the viewer would offer to navigate and
     * silently do nothing on whichever kinds were missed, and which kinds those are is invisible
     * from the outside. Every node has a declaration or an expression to point at - a RETURN node
     * and a parameter have the method's, and a METHOD box is a declaration itself - so there is no
     * node in the graph with nothing honest to say.
     *
     * `funcCall` is the fixture because it has calls nested three deep, so a callee's nodes are
     * built while the *caller's* context is the one in hand. Taking that one would name the wrong
     * file as soon as a call crosses one, which no single-file fixture can show.
     */
    @Test
    fun everyNodeCarriesASource() {
        val nodes = jsonNodes(buildJson("funcCall", listOf("App.java")))
        val missing = nodes.filter { jsonSource(it).isNullOrBlank() }.map { jsonLabel(it) }
        assertTrue(missing.isEmpty(), "nodes with no source position: $missing")
    }

    /**
     * A method that calls itself is inlined once, and the call inside it is opaque.
     *
     * Inlining happens per call site with no in-progress set, so a recursive method had nothing
     * stopping it: `fact` took the run down with a StackOverflowError, no output at all, and a stack
     * trace naming the graph builder rather than a line of Java. A five-line factorial reaches it.
     *
     * The opaque node is the same answer a call outside the analysed sources gets, and it is honest
     * about what happened - a call whose body was not inlined any further, arguments in, result out.
     * The decision was recorded in `plan-for-these-improvements-mighty-prism.md` before this was
     * written, so it is settled rather than invented here.
     *
     * The outer call is still inlined, which is what distinguishes this from giving up on recursion
     * entirely: `seed` reaches the parameter, and only the second entry into `fact` is cut.
     */
    @Test
    fun aRecursiveCallIsOpaqueAndTheOuterCallIsStillInlined() {
        val graph = buildGraph("recursion", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("fact" to "EXTERNAL" in nodeTypes(graph), "the recursive call is not opaque: ${nodeTypes(graph)}")
        assertTrue("seed" to "n" in edges, "the outer call was not inlined: $edges")
        assertTrue("-" to "fact" in edges, "the argument does not reach the recursive call: $edges")
        assertTrue("fact" to "*" in edges, "the recursive call's result does not flow out: $edges")
    }

    /**
     * The variable of an enhanced `for` is bound to what is being iterated, and the body can read it.
     *
     * Nothing bound it before, so every read in the body found no node and took the run down - and
     * the gate in `scan` covers expressions only, so the failure named a missing identifier several
     * lines from the loop that should have declared it, rather than naming the loop.
     */
    @Test
    fun theVariableOfAnEnhancedForIsBoundToWhatIsIterated() {
        val graph = buildGraph("enhancedFor", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("names" to "name" in edges, "the collection does not reach the loop variable: $edges")
        assertTrue("name" to "length" in edges, "the loop variable does not reach the body: $edges")
        assertTrue(reaches(graph, "names", "total"), "the elements do not reach what the body computes: $graph")
    }

    /**
     * An enum constant is a value whichever way it is written.
     *
     * `Size.SMALL` was already a value with nothing flowing into it - the declaration is the value,
     * so there is no assignment to find. A bare `LARGE` inside the enum is the same thing written
     * shorter, and used to be a hard failure instead: `case 1 -> FLAT` in a `fromInt` switch, which
     * is on nearly every enum in a real codebase.
     */
    @Test
    fun anEnumConstantIsAValueBareOrQualified() {
        val graph = buildGraph("enumConstant", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("LARGE" to "ternary" in edges, "the bare constant does not reach the selection: $edges")
        assertTrue("SMALL" to "ternary" in edges, "the qualified constant does not reach the selection: $edges")
        assertTrue(
            edges.none { it.second == "LARGE" || it.second == "SMALL" },
            "a constant is drawn with something flowing into it: $edges"
        )
    }

    /**
     * A lambda's body is drawn, and what it captures flows through it.
     *
     * Failing on every lambda stopped codeflow dead on most modern Java, and drawing it as one
     * opaque box would hide source the reader can see - the same black box the nested-class defect
     * produced. The body is walked in the enclosing block because nothing here calls the lambda, so
     * there is no call site to nest it under.
     */
    @Test
    fun aLambdaBodyIsDrawnAndWhatItCapturesFlowsThrough() {
        val graph = buildGraph("lambda", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("base" to "*" in edges, "the captured value does not reach the body: $edges")
        assertTrue("*" to "lambda" in edges, "the body does not reach the function value: $edges")
        assertTrue(reaches(graph, "3", "lambda"), "the captured value does not survive the lambda: $graph")
    }

    /**
     * A lambda with a statement body returns to the lambda, not to the method around it.
     *
     * Its body is walked in the enclosing method's block, so a `return` inside it would otherwise
     * be wired to that method's return node - an edge asserting `main` returns a value it does not,
     * which is exactly the plausible-and-wrong diagram the gate exists to prevent.
     */
    @Test
    fun aStatementBodiedLambdaReturnsToItselfNotToTheMethodAroundIt() {
        val graph = buildGraph("statementLambda", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("+" to "lambda" in edges, "the body does not reach the function value: $edges")
        assertTrue(edges.none { it.second == "main" }, "the lambda returns into the enclosing method: $edges")
    }

    /**
     * A field read before anything assigns it is a value with nothing flowing into it, and does not
     * stop the fields around it being tracked.
     *
     * This used to be a hard failure, on the grounds that a tracked object should know its own
     * fields. It should not: a builder left half-filled and then copied field by field is the usual
     * shape of real code, and `builder.neverSet` there is Java's default rather than something the
     * analysis lost. Taking the run down over it stopped every diagram containing one.
     */
    @Test
    fun aFieldReadBeforeItIsAssignedIsAValueRatherThanAFailure() {
        val graph = buildGraph("unassignedField", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("neverSet" to "fromNeverSet" in edges, "the unassigned field does not reach the copy: $edges")
        assertTrue(
            edges.none { it.second == "neverSet" },
            "the unassigned field is drawn with something flowing into it: $edges"
        )
        assertTrue(reaches(graph, "4", "out"), "the assigned field alongside it lost its value: $graph")
    }

    /**
     * A local with no value is still a failure, and says where.
     *
     * This is the other half of [aFieldReadBeforeItIsAssignedIsAValueRatherThanAFailure]: a local
     * cannot be read before it is written, so not finding one means either the analysis lost it or
     * the program never wrote it. Letting every missing name through as a value from nowhere would
     * turn the loud failure into a plausible diagram, which is the trade this project refuses to
     * make.
     *
     * The fixture is one the compiler rejects, which codeflow still has to have an answer for:
     * attribution runs on sources that do not compile, since a tool pointed at a directory nobody
     * has read cannot require it to build. It replaced `unboundLocal`, whose gap was in codeflow and
     * has since been closed - see [codeflow.ir.IrGraphBuilderTest.aPatternOnASwitchStatementBindsItsName].
     */
    @Test
    fun aLocalWithNoValueStillFails() {
        val thrown = assertFailsWith<GraphException> {
            buildGraph("unwrittenLocal", listOf("App.java"))
        }
        assertTrue(
            thrown.message!!.contains("unwrittenLocal/App.java:19"),
            "the failure does not say which line: ${thrown.message}"
        )
    }

    /**
     * `SMALL(3)` runs a constructor, so the value written into the constant is the one its getter
     * returns - and each constant is its own object.
     *
     * Nothing ran the declaration, so `Size.SMALL` was opaque and `units()` was inlined against an
     * object with no fields: it returned a `units` with nothing flowing into it. That is a getter
     * drawn as producing a value from nowhere, on the shape most enums in real code have.
     *
     * The negative assertion is what says the constants are two objects rather than one; it is
     * paired with the two positives, which fail if nothing is connected at all.
     *
     * Ported from codemap's `enum` fixture. The bare form, where the declaration is the whole
     * value, stays as it was - see [anEnumConstantIsAValueBareOrQualified].
     */
    @Test
    fun anEnumConstantsConstructorArgumentReachesItsGetter() {
        val graph = buildGraph("enumConstructor", listOf("App.java"))
        assertTrue("units" to "VARIABLE" in nodeTypes(graph), "the constant's field is not tracked: ${nodeTypes(graph)}")
        assertTrue(reaches(graph, "3", "small"), "the first constant's argument does not reach its getter: $graph")
        assertTrue(reaches(graph, "9", "large"), "the second constant's argument does not reach its getter: $graph")
        assertTrue(!reaches(graph, "3", "large"), "the two constants share one object: $graph")
    }

    /**
     * A field initializer and an instance initializer block run as part of construction, so what
     * they assign is what the constructor reads and what the caller finds afterwards.
     *
     * Nothing outside a method body was ever walked. `counted = counted + add` therefore read a
     * `counted` with nothing flowing into it, `blocked` came back as a field nobody had assigned,
     * and `nested` named an object that had never been constructed, so `outer.nested.held` was an
     * opaque dead end. All three are complete, readable drawings of flows that are not the code's.
     *
     * `Plain` declares no constructor, so there is no body to inline and no box to draw - the
     * initializer still runs. The `add` assertion is what says the initializer did not simply
     * replace what the constructor does.
     *
     * Ported from codemap's `constructor_chain` fixture.
     */
    @Test
    fun fieldInitializersAndInstanceBlocksRunAsPartOfConstruction() {
        val graph = buildGraph("fieldInitializer", listOf("App.java"))
        assertTrue(reaches(graph, "5", "fromField"), "the field initializer did not run: $graph")
        assertTrue(reaches(graph, "3", "fromField"), "the constructor's own write was lost: $graph")
        assertTrue(reaches(graph, "7", "fromBlock"), "the instance initializer block did not run: $graph")
        assertTrue(reaches(graph, "10", "fromNested"), "an object built by a field initializer is not tracked: $graph")
        assertTrue(reaches(graph, "4", "fromPlain"), "a class with no written constructor skipped its initializer: $graph")
        assertTrue(reaches(graph, "1", "fromDelegated"), "the delegating constructor's chain is broken: $graph")
        // Two `new Outer(...)`, so `counted = 5` runs twice. A third occurrence means the
        // constructor delegated to ran the initializers that its `this(...)` caller had already run.
        assertEquals(
            2, nodeTypes(graph).count { it == ("5" to "LITERAL") },
            "the field initializer is drawn once per construction: ${nodeTypes(graph)}"
        )
    }

    /**
     * A `switch` used as a statement compares its selector against every case label, and walks
     * every arm.
     *
     * The selector's read was invisible: `visitSwitchExpression` models the expression form, there
     * was no `visitSwitch`, and a *statement* is not covered by the gate in `scan`, so nothing said
     * so. The default scan reached the selector and produced its node, then drew no edge out of it,
     * which is a diagram where the value that decides the whole branch appears to be unused.
     *
     * The count is what makes this fail on a plausible-but-wrong implementation: comparing the
     * selector once, or once per arm including `default`, both draw a switch that reads its
     * selector. Three constant labels means three comparisons.
     *
     * Ported from codemap's `switch` fixture.
     */
    @Test
    fun aSwitchStatementComparesItsSelectorAgainstEveryLabel() {
        val graph = buildGraph("switchStatement", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertEquals(
            3, edges.count { it == ("selector" to "==") },
            "the selector is not compared against each of the three constant labels: $edges"
        )
        assertTrue("1" to "==" in edges, "the first case label is not compared: $edges")
        assertTrue("2" to "==" in edges, "the second case label is not compared: $edges")
        assertTrue("3" to "==" in edges, "the third case label is not compared: $edges")
        assertTrue("10" to "chosen" in edges, "the first arm was not walked: $edges")
        assertTrue("300" to "side" in edges, "the fall-through arm was not walked: $edges")
        assertTrue("500" to "side" in edges, "the default arm was not walked: $edges")
        assertTrue(reaches(graph, "100", "out"), "the value the switch left behind does not reach the read: $graph")
    }

    /**
     * With several entry points, the one graphed is the first by source path, whichever order the
     * files arrive in.
     *
     * The whole diagram is whatever that one method reaches, and the choice used to come out of a
     * HashMap: on a corpus with three `main`s it picked one reaching a single file and drew that,
     * complete and plausible, as the codebase. Order-independence is the testable half of the fix;
     * the other half is that the run says on stderr which one it took and what it passed over.
     */
    @Test
    fun theEntryPointIsChosenTheSameWayWhateverOrderTheFilesArriveIn() {
        val alphaFirst = edgeLabels(buildGraph("twoMains", listOf("Alpha.java", "Zeta.java")))
        val zetaFirst = edgeLabels(buildGraph("twoMains", listOf("Zeta.java", "Alpha.java")))
        assertTrue("fromAlpha" to "+" in alphaFirst, "the first main by path was not the one graphed: $alphaFirst")
        assertEquals(alphaFirst, zetaFirst, "the file order decided which main was graphed")
    }

    /**
     * Two entry points sharing a static field are one graph, joined by a `shared` edge from the
     * write to the read, and the join does not depend on which was named first.
     *
     * `configure` writes `Settings.rate` and `quote` reads it, so `newRate` reaches what `quote`
     * returns - through the field and nothing else. The edge is `shared` rather than plain flow
     * because it holds only if `configure` ran first, which nothing here knows. Each entry point is
     * drawn as it would be alone: `quote` on its own has no value for `rate`, and `configure` on
     * its own draws the write with nothing reading it.
     */
    @Test
    fun entryPointsShareAStaticFieldWhateverOrderTheyAreNamedIn() {
        val both = listOf("Api#configure", "Api#quote")
        val graph = buildGraph("twoEntryPoints", listOf("Api.java"), from = both)
        val edges = edgeLabels(graph)
        assertTrue(reaches(graph, "newRate", "price"), "the written value does not reach the read: $edges")
        assertTrue(reaches(graph, "newRate", "quote"), "the written value does not reach what quote returns: $edges")
        val shared = graph.filter { it.contains(" -. shared .-> ") }
        assertEquals(1, shared.size, "expected exactly one shared edge: $shared")
        assertTrue(shared.single().startsWith("  n") && shared.single().contains("[rate]:::VARIABLE -. shared .-> "),
            "the shared edge is not the write of rate into quote's read: $shared")
        assertTrue(shared.single().endsWith("[rate]:::VARIABLE"), "the shared edge does not end at the read: $shared")
        // Without the shared edge there is no way from configure to quote at all.
        val withoutShared = graph.filterNot { it.contains(" -. shared .-> ") }
        assertTrue(!reaches(withoutShared, "newRate", "price"), "something other than the field connects them")

        val swapped = edgeLabels(buildGraph("twoEntryPoints", listOf("Api.java"), from = both.reversed()))
        assertEquals(edges.map { it.toString() }.sorted(), swapped.map { it.toString() }.sorted(), "the order of --from changed the graph")

        val configureOnly = edgeLabels(buildGraph("twoEntryPoints", listOf("Api.java"), from = listOf("Api#configure")))
        assertTrue("newRate" to "*" in configureOnly, "configure alone was not built: $configureOnly")
        val quoteOnlyGraph = buildGraph("twoEntryPoints", listOf("Api.java"), from = listOf("Api#quote"))
        val quoteOnly = edgeLabels(quoteOnlyGraph)
        assertTrue("amount" to "*" in quoteOnly, "quote alone was not built: $quoteOnly")
        assertTrue(quoteOnly.none { it.second == "rate" }, "quote alone has something flowing into rate: $quoteOnly")
        assertTrue(quoteOnlyGraph.none { it.contains("shared") }, "a single entry point drew a shared edge")
    }

    /**
     * `args[position]` takes a value out of the array, and which one depends on the index, so both
     * flow into it. `[]` cannot be the label: square brackets delimit a node in Mermaid.
     */
    @Test
    fun arrayAccessIsAValueFromBothTheArrayAndTheIndex() {
        val edges = edgeLabels(buildGraph("arrayAccess", listOf("App.java")))
        assertTrue("args" to "index" in edges, "the array does not reach the access: $edges")
        assertTrue("position" to "index" in edges, "the index does not reach the access: $edges")
        assertTrue("index" to "picked" in edges, "the access does not reach the variable: $edges")
        assertTrue("picked" to "length" in edges, "flow does not continue past the access: $edges")
    }

    /**
     * `new int[size]` and `new int[] { seed, 9 }` are both values built out of what is written
     * inside them, so the size and the elements flow into the array.
     *
     * The size counts as much as an element does. It is not what the array holds, but it is what
     * decides how much of it there is, and an array drawn with nothing flowing in reads as a value
     * that came from nowhere - the same wrongness as any other dropped operand.
     */
    @Test
    fun anArrayIsBuiltFromItsSizeAndItsElements() {
        val graph = buildGraph("arrayCreation", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("size" to "array" in edges, "the size does not reach the array: $edges")
        assertTrue("seed" to "array" in edges, "an element does not reach the array: $edges")
        assertTrue("array" to "sized" in edges, "the array does not reach the variable: $edges")
        assertTrue("array" to "filled" in edges, "the array does not reach the variable: $edges")
        assertTrue(reaches(graph, "seed", "out"), "flow does not continue past the array: $edges")
    }

    /**
     * `catch (NumberFormatException failure)` binds a name the handler then reads.
     *
     * Nothing flows into it. Which throw reached this handler is control flow, and codeflow models
     * none, so the honest drawing is a value with no source - the same answer a lambda parameter
     * gets. What it must not be is absent: the gate in `scan` only covers expressions, so an
     * unmodelled *statement* names nothing and surfaces further down as a read of a name that has
     * no node, taking the whole run out on a line that is not the one at fault.
     */
    @Test
    fun aCaughtExceptionIsAValueTheHandlerCanRead() {
        val graph = buildGraph("catchParameter", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("failure" to "getMessage" in edges, "the caught exception is not read: $edges")
        assertTrue("getMessage" to "reason" in edges, "the read does not reach the variable: $edges")
        assertTrue(reaches(graph, "failure", "out"), "flow does not continue out of the handler: $edges")
    }

    /**
     * A call written with no receiver runs on the enclosing instance, so a field it writes is a
     * write to the object the outer call was made on, and the caller's read afterwards finds it.
     *
     * Only the receiver written at the call site was used, and an unqualified call has none, so the
     * callee was inlined with no owner and its write landed on nothing anyone could look up. One
     * level deep hid it - `gauge.record()` has a receiver - and two levels did not, so the caller's
     * read quietly kept the value from before the call. The negative assertion is what says the
     * write replaced rather than merely joined, and is paired with the positive above it.
     *
     * Ported from codemap's `deep_method` fixture.
     */
    @Test
    fun aFieldWrittenTwoCallsDeepReachesTheCaller() {
        val graph = buildGraph("deepField", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("18" to "reading" in edges, "the innermost write is missing: $edges")
        assertTrue(reaches(graph, "18", "taken"), "the write two calls down does not reach the caller: $edges")
        assertTrue(!reaches(graph, "17", "taken"), "the value from before the call was not replaced: $edges")
    }

    /**
     * `x = x + 1` reads x before it writes it, so the operand is the value x held going in.
     *
     * The target used to be created first, which registered it as the current value of x under the
     * same key, so the x in the expression found the node about to be written. That draws a cycle -
     * `x -> + -> x` on one box - orphans the previous value, and cuts the literal that produced it
     * off from everything downstream. `x += 1` was always right, because it evaluates the variable
     * first, so the two spellings of one statement disagreed. The assertion is on all three forms
     * for that reason.
     *
     * Found while porting codemap's `static_member`, where `total = total + by` made the write
     * unreachable from the read that fed it.
     */
    @Test
    fun anAssignmentReadsTheValueTheVariableHeldGoingIn() {
        val graph = buildGraph("selfAssignment", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue(reaches(graph, "1", "expanded"), "the previous value is orphaned by `x = x + n`: $edges")
        assertTrue(reaches(graph, "10", "expanded"), "the added value does not reach the result: $edges")
        assertTrue(reaches(graph, "2", "compound"), "the previous value is orphaned by `x += n`: $edges")
        assertTrue(reaches(graph, "3", "field"), "the previous value of a field is orphaned: $edges")
        assertTrue(reaches(graph, "30", "field"), "the added value does not reach the field: $edges")
    }

    /**
     * `Counter.total` and a bare `total` inside `Counter` are one variable, so a write through
     * either form has to be found by a read through the other.
     *
     * A static has no instance, so the MemPos that carries an instance field is not available, and
     * the block-parent chain is the wrong shape to fall back on: `bump`'s block is a *child* of
     * `main`'s, so a read in `main` after the call cannot walk to it. Written out, the qualified
     * form degraded to an opaque EXTERNAL node - both reads collapsed onto one, and `bump`'s write
     * reached neither. The type assertion is what catches that; it is paired with the reachability
     * ones, which fail if nothing is connected at all.
     *
     * Ported from codemap's `static_member` and `global_var` fixtures.
     */
    @Test
    fun aStaticFieldIsOneVariableQualifiedOrNot() {
        val graph = buildGraph("staticField", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("total" to "VARIABLE" in nodeTypes(graph), "the static field is not a variable: $edges")
        assertTrue("total" to "EXTERNAL" !in nodeTypes(graph), "the static field went opaque: ${nodeTypes(graph)}")
        assertTrue(reaches(graph, "5", "before"), "the qualified write does not reach the qualified read: $edges")
        assertTrue(reaches(graph, "5", "after"), "the value before the call does not survive it: $edges")
        assertTrue(reaches(graph, "3", "after"), "the unqualified write inside bump is not seen by main: $edges")
    }

    /**
     * A method leaves by whichever `return` runs, so each one produces the method's value and all
     * of them have to reach the RETURN node. Keeping only the last would draw the guard clauses as
     * dead code - readable, plausible, and claiming the method can only ever return one thing.
     *
     * Ported from codemap's `return` fixture.
     *
     * Asked with [reaches] rather than on adjacent edges because a guarded exit joins through the
     * choosing its guard gates - see [theGuardOfAnEarlyReturnReachesTheValueItDecides]. That every
     * one of the three still arrives is the claim, and it is the half of it a gate could have
     * broken: folding the exits is where a value the method really can produce would go missing.
     */
    @Test
    fun everyReturnInAMethodProducesItsValue() {
        val graph = buildGraph("earlyReturn", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue(reaches(graph, "100", "classify"), "the first guard's return is missing: $edges")
        assertTrue(reaches(graph, "55", "classify"), "the second guard's return is missing: $edges")
        assertTrue(reaches(graph, "*", "classify"), "the fall-through return is missing: $edges")
        assertTrue("classify" to "result" in edges, "the method's value does not reach the caller: $edges")
    }

    /**
     * The guard of an early `return` reaches the value it decides, as the condition of an `if` that
     * writes a variable already does.
     *
     * `if (v > 100) { return r; }` above a `return s` is a choice between two values, and it used to
     * be drawn as two plain arrows into the RETURN node with the comparison that chose sitting on
     * the page with no edge leaving it at all. That is [theConditionOfAnIfReachesEachValueItDecides]'
     * wound in the one place the join for a variable never looked: a guarded exit does not reach the
     * join below the `if`, so nothing gated it and nothing said so.
     *
     * `if2` has the two shapes side by side. The outer `if` falls out of its own bottom on both
     * paths, so `r` joins below it in the ordinary way; the inner one leaves the method, so its
     * value joins at the exit. Three gated joins, and the counts are the assertion so that a run
     * gating all of them or none of them fails.
     */
    @Test
    fun theGuardOfAnEarlyReturnReachesTheValueItDecides() {
        val graph = buildGraph("if2", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertEquals(4, graph.count { it.contains("-->|if|") }, "a condition does not reach its join: $graph")
        assertEquals(4, graph.count { it.contains("-->|true|") }, "the true paths are not marked: $graph")
        assertEquals(4, graph.count { it.contains("-->|false|") }, "the false paths are not marked: $graph")
        assertTrue("if" to "classify" in edges, "the choice does not reach the method's value: $edges")
        assertFalse("s" to "classify" in edges, "the fall-through arrives ungated: $edges")
        assertTrue(reaches(graph, "1", "classify"), "the guarded return does not reach the method's value")
        assertTrue(reaches(graph, "2", "classify"), "the fall-through does not reach the method's value")
    }

    /**
     * When both arms of an `if` leave the method, the choice between them is still drawn.
     *
     * There is no path falling through for the guard to choose against, so the older exit is what
     * the younger one is gated against - the case the fold would otherwise have no second value for,
     * and `int f(x) { if (c) return a; else return b; }` is ordinary Java rather than a corner.
     * Both arms named, and neither arriving at the result on its own.
     */
    @Test
    fun bothArmsOfAnIfThatLeavesTheMethodStillJoin() {
        val edges = edgeLabels(buildGraph("if2", listOf("App.java")))
        assertTrue("6" to "if" in edges, "the value returned by the true arm is missing: $edges")
        assertTrue("7" to "if" in edges, "the value returned by the false arm is missing: $edges")
        assertTrue("if" to "either" in edges, "the choice does not reach the method's value: $edges")
        assertFalse("6" to "either" in edges, "the true arm arrives ungated: $edges")
        assertFalse("7" to "either" in edges, "the false arm arrives ungated: $edges")
    }

    /**
     * A field is declared once, on whichever class in the chain declares it, and a read through a
     * subclass has to find that one. `Leaf` declares neither `fromBase` nor `fromMiddle`, so
     * looking a field up on the receiver's own class would lose both.
     *
     * Ported from codemap's `inheritance` fixture, which used two base classes; Java has one.
     */
    @Test
    fun aFieldDeclaredOnASuperclassIsReadThroughTheSubclass() {
        val graph = buildGraph("inheritance", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("5" to "fromBase" in edges, "the grandparent's field is not written: $edges")
        assertTrue("10" to "fromMiddle" in edges, "the parent's field is not written: $edges")
        assertTrue("20" to "fromLeaf" in edges, "the subclass's own field is not written: $edges")
        assertTrue(reaches(graph, "5", "total"), "the grandparent's field does not reach the sum: $edges")
        assertTrue(reaches(graph, "10", "total"), "the parent's field does not reach the sum: $edges")
        assertTrue(reaches(graph, "20", "total"), "the subclass's field does not reach the sum: $edges")
    }

    /**
     * Three ways to reach a method declared on a superclass - through `super`, unqualified, and as
     * an inherited static - and all three have a body in the analysed sources, so all three are
     * inlined rather than taking the opaque EXTERNAL path.
     *
     * Ported from codemap's `parent_class_method` fixture.
     */
    @Test
    fun anInheritedMethodIsInlinedHoweverItIsReached() {
        val graph = buildGraph("parentMethod", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("input" to "amount" in edges, "the argument does not reach super.shift's parameter: $edges")
        assertTrue("amount" to "+" in edges, "super.shift's body was not inlined: $edges")
        assertTrue("offset" to "+" in edges, "the field the parent method reads is missing: $edges")
        // `super.m()` runs on the object the caller is running on, so the field the subclass wrote
        // is the one the parent method reads. Without this the edge above is still drawn, from a
        // fresh `offset` with nothing flowing into it - the same picture, asserting a value that
        // never arrives.
        assertTrue(reaches(graph, "5", "out"), "the subclass's write is not what super.shift reads: $edges")
        assertTrue("shift" to "shifted" in edges, "super.shift does not return its value: $edges")
        assertTrue("shifted" to "factor" in edges, "the argument does not reach the inherited static: $edges")
        assertTrue("factor" to "*" in edges, "the inherited static's body was not inlined: $edges")
        assertTrue("scale" to "scaled" in edges, "the inherited static does not return its value: $edges")
    }

    /**
     * Two names for one object. A write through the alias is a write to the object, so the read
     * after the block finds it - and finds it *instead of* the value written before the block,
     * since one assignment replaced the other rather than adding to it.
     *
     * The negative half is paired with the positive: an implementation that connected nothing
     * would satisfy "1 does not reach read" trivially, and fail the line above it.
     *
     * Ported from codemap's `write_pointed_inside_block` fixture.
     */
    @Test
    fun aWriteThroughAnAliasInANestedBlockIsSeenAfterIt() {
        val graph = buildGraph("aliasInBlock", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("box" to "alias" in edges, "the alias is not bound to the object: $edges")
        assertTrue(reaches(graph, "7", "read"), "the write through the alias is not seen after the block: $edges")
        assertTrue(!reaches(graph, "1", "read"), "the replaced value still reaches the read: $edges")
    }

    /**
     * A type parameter is a type like any other. The value put in through the constructor is the
     * one the getter returns, whatever `T` was bound to at the call site.
     *
     * Ported from codemap's `template` fixture.
     */
    @Test
    fun aValueFlowsThroughAGenericHolder() {
        val graph = buildGraph("generic", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("\"payload\"" to "initial" in edges, "the argument does not reach the constructor: $edges")
        assertTrue("initial" to "held" in edges, "the constructor does not write the field: $edges")
        assertTrue("held" to "get" in edges, "the getter does not return the field: $edges")
        assertTrue("get" to "taken" in edges, "the getter's value does not reach the caller: $edges")
        assertTrue(reaches(graph, "\"payload\"", "length"), "flow does not continue past the holder: $edges")
    }

    /**
     * The callee is in another package, in a subdirectory. Resolution is by `Element`, so where a
     * file sits on disk decides nothing about what its names mean.
     *
     * Ported from codemap's `files` fixture, which kept callees under `sub_folder/`.
     */
    @Test
    fun aCalleeInASubdirectoryAndAnotherPackageIsInlined() {
        val edges = edgeLabels(buildGraph("subpackage", listOf("App.java", "util/Adder.java")))
        assertTrue("3" to "left" in edges, "the first argument does not reach the parameter: $edges")
        assertTrue("5" to "right" in edges, "the second argument does not reach the parameter: $edges")
        assertTrue("left" to "+" in edges, "the callee's body was not inlined: $edges")
        assertTrue("add" to "sum" in edges, "the callee's value does not reach the caller: $edges")
    }

    /**
     * `value instanceof String` is a value derived from `value`, and `value instanceof String text`
     * additionally binds `text` to the very same object.
     *
     * Without the binding the graph is not merely missing an edge: every later read of `text` is a
     * name that resolves to nothing, so the whole method fails. With it, the object has to be the
     * one tested, not a new one, or a receiver's fields are looked for in the wrong place.
     */
    @Test
    fun instanceOfTestsAValueAndBindsThePatternToIt() {
        val edges = edgeLabels(buildGraph("instanceOf", listOf("App.java")))
        assertTrue("value" to "instanceof" in edges, "the tested value does not reach the test: $edges")
        assertTrue("instanceof" to "isText" in edges, "the test does not reach the variable: $edges")
        assertTrue("value" to "text" in edges, "the pattern variable is not bound to the tested value: $edges")
        assertTrue("text" to "length" in edges, "the pattern variable is not usable as a receiver: $edges")
    }

    /**
     * Two methods named `twice`, one taking an int and one a String. Which body runs at a call
     * site is decided by the argument types, so a lookup by name has to pick one and be wrong at
     * half the call sites - silently, since the body it inlines is real code that reads fine.
     */
    @Test
    fun overloadsResolveToTheBodyThatRuns() {
        val edges = edgeLabels(buildGraph("overload", listOf("App.java")))
        assertTrue("number" to "value" in edges, "int argument does not reach the int parameter: $edges")
        assertTrue("value" to "*" in edges, "the int overload's body was not inlined: $edges")
        assertTrue("*" to "scaled" in edges, "the int overload's body was not inlined: $edges")
        assertTrue("\"abc\"" to "text" in edges, "String argument does not reach the String parameter: $edges")
        assertTrue("text" to "length" in edges, "the String overload's body was not inlined: $edges")
        assertTrue("length" to "counted" in edges, "the String overload's body was not inlined: $edges")
    }

    /**
     * `Account.close()` and `Connection.close()` are different methods that happen to share a name.
     * Keyed by name they were one entry, so both call sites were drawn with the same body.
     */
    @Test
    fun sameMethodNameOnTwoClassesStaysTwoMethods() {
        val edges = edgeLabels(buildGraph("sameName", listOf("App.java")))
        assertTrue("-" to "settled" in edges, "Account.close's body is missing: $edges")
        assertTrue("+" to "flushed" in edges, "Connection.close's body is missing: $edges")
        assertTrue("settled" to "close" in edges, "Account.close does not return its value: $edges")
        assertTrue("flushed" to "close" in edges, "Connection.close does not return its value: $edges")
    }

    /**
     * `total` names both an int field and a Holder local. Whether a variable holds a value or a
     * reference decides how it is modelled, and reading that off a map keyed by bare name let the
     * last declaration parsed answer for every `total` in the sources.
     */
    @Test
    fun sameNameWithTwoTypesIsModelledByType() {
        val nodes = nodeTypes(buildGraph("shadowedType", listOf("App.java")))
        assertTrue("total" to "OBJ_VARIABLE" in nodes, "the Holder local is not an object: $nodes")
        assertTrue("total" to "VARIABLE" in nodes, "the int field is not a value: $nodes")
    }

    /**
     * The tool is pointed at sources with no classpath, so most of a real file's types cannot be
     * resolved. That has to degrade to the opaque external node, not to a failure and not to a
     * guess - this is the guard on codeflow still working on the input it exists for.
     */
    @Test
    fun unresolvableTypeStaysOpaqueAndTraceable() {
        val edges = edgeLabels(buildGraph("unresolvedType", listOf("App.java")))
        assertTrue("size" to "create" in edges, "argument does not reach the unresolvable call: $edges")
        assertTrue("create" to "widget" in edges, "call result does not reach the variable: $edges")
        assertTrue("widget" to "measure" in edges, "receiver does not reach the call made on it: $edges")
        assertTrue("+" to "total" in edges, "flow does not continue past the unresolvable type: $edges")
    }

    /**
     * outer() and inner() each declare a local `amount` on the same instance. They are two
     * variables, and the value read back in outer() is the one outer() assigned.
     *
     * Keyed by name and instance they were one, and both were filed on the same MemPos under that
     * one key, so the callee's assignment overwrote the caller's and outer() read inner()'s value.
     * The labels cannot tell the two apart, which is the point: on the diagram this was invisible.
     */
    @Test
    fun localsOfTheSameNameInTwoMethodsStayApart() {
        val graph = buildGraph("collidingLocals", listOf("App.java"))
        assertTrue(reaches(graph, "1", "afterwards"), "outer's own value does not reach it: $graph")
        assertTrue(!reaches(graph, "2", "afterwards"), "the callee's value leaked into the caller: $graph")
        assertTrue(reaches(graph, "2", "consumed"), "inner's value does not reach its own read: $graph")
    }

    /**
     * The method boundary is what a viewer draws as a rectangle, so a call has to come out as a
     * node nested inside its caller's node - that containment *is* the boundary in GraphML, there
     * is no separate notion of a group. Flat output would still render, as a correct graph with
     * every method boundary silently gone.
     */
    @Test
    fun graphmlNestsACallInsideItsCaller() {
        val doc = buildGraphml("funcCall", listOf("App.java"))
        val blocks = elements(doc, "node").filter { dataOf(it, "type") == "METHOD" }
        val methodC = blocks.filter { labelOf(it) == "methodC" }
        assertEquals(2, methodC.size, "methodC is inlined at two call sites and should appear twice")
        assertTrue(methodC.all { enclosingBlockLabel(it) == "methodB" }, "methodC is not nested in methodB")

        val methodB = blocks.single { labelOf(it) == "methodB" }
        assertEquals("main", enclosingBlockLabel(methodB), "methodB is not nested in main")

        val paramH = elements(doc, "node").filter { labelOf(it) == "paramH" }
        assertTrue(paramH.isNotEmpty(), "methodC's parameter is missing")
        assertTrue(paramH.all { enclosingBlockLabel(it) == "methodC" }, "a node escaped its own method")
    }

    /**
     * `<init>`, `<`, `>` and a quoted literal are all real labels, and all of them are XML syntax.
     * Written raw they produce a document a viewer refuses to open, or worse, one it opens with the
     * label truncated at the first bad character.
     */
    @Test
    fun graphmlEscapesLabelsThatAreXmlSyntax() {
        val constructor = elements(buildGraphml("constructor", listOf("App.java")), "node").map { labelOf(it) }
        assertTrue("<init>" in constructor, "the constructor's return label did not survive: $constructor")
        assertTrue("\"test\"" in constructor, "the string literal's label did not survive: $constructor")

        val operators = elements(buildGraphml("operators", listOf("App.java")), "node").map { labelOf(it) }
        assertTrue("<" in operators, "the less-than operator did not survive: $operators")
        assertTrue(">=" in operators, "the greater-or-equal operator did not survive: $operators")
    }

    /**
     * The two exporters render one graph, so they have to agree on it. The risk is specific: an
     * edge can cross a method boundary - a return flows to the variable in the caller - and GraphML
     * requires such an edge to be declared in a graph enclosing both ends, unlike Mermaid, which
     * takes it anywhere. Getting that wrong drops exactly the edges that join methods together.
     */
    @Test
    fun graphmlKeepsEveryEdgeTheMermaidGraphHas() {
        val mermaid = edgeLabels(buildGraph("funcCall", listOf("App.java")), events = true).sortedBy { it.toString() }
        val graphml = graphmlEdgeLabels(buildGraphml("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        assertEquals(mermaid, graphml, "the two renderings of one graph disagree on its edges")
    }

    /**
     * `parent` is what Cytoscape draws as a containing box, so it is the method boundary and
     * nothing else carries it. A payload with the nesting flattened renders as a correct graph
     * with every boundary silently gone.
     */
    @Test
    fun jsonNestsACallInsideItsCaller() {
        val doc = buildJson("funcCall", listOf("App.java"))
        val nodes = jsonNodes(doc)
        val byId = nodes.associateBy { it.get("id").asString }

        val root = nodes.single { jsonParent(it) == null }
        assertEquals("main", jsonLabel(root), "the parentless node should be the outermost method")

        val methodC = nodes.filter { jsonLabel(it) == "methodC" && it.get("type").asString == "METHOD" }
        assertEquals(2, methodC.size, "methodC is inlined at two call sites and should appear twice")
        assertTrue(
            methodC.all { jsonLabel(byId.getValue(jsonParent(it)!!)) == "methodB" },
            "methodC is not nested in methodB"
        )

        val paramH = nodes.filter { jsonLabel(it) == "paramH" }
        assertTrue(paramH.isNotEmpty(), "methodC's parameter is missing")
        assertTrue(
            paramH.all { jsonLabel(byId.getValue(jsonParent(it)!!)) == "methodC" },
            "a node escaped its own method"
        )
    }

    /**
     * A label carrying a quote ends the JSON string early and the rest of the payload becomes
     * syntax errors, so the page renders nothing at all.
     */
    @Test
    fun jsonEscapesLabelsThatAreJsonSyntax() {
        val labels = jsonNodes(buildJson("constructor", listOf("App.java"))).map { jsonLabel(it) }
        assertTrue("\"test\"" in labels, "the string literal's label did not survive: $labels")
        assertTrue("<init>" in labels, "the constructor's return label did not survive: $labels")
    }

    private fun jsonOf(roots: List<GraphBuilderBlock>): JsonObject {
        val text = StringBuilder()
        JsonExporter(testResourcesPath).processMainMethod(roots) { text.append(it).append("\n") }
        return JsonParser.parseString(text.toString()).asJsonObject
    }

    /**
     * A box names its method as javac resolved it, and says when it is a boundary method's block -
     * which is what the condensed view groups by, so a boundary told by its label instead would be
     * the guess the payload exists to avoid. Every block of a boundary method carries it, and the
     * entry point's does not.
     */
    @Test
    fun jsonNamesEachBoxsMethodAndMarksBoundaryBlocks() {
        val boxes = jsonNodes(jsonOf(boundaryRootBlocks())).filter { it.get("type").asString == "METHOD" }
        val func1 = boxes.single { jsonLabel(it) == "boundaryfunc1" }
        assertEquals("boundary.Boundary#boundaryfunc1(int)", func1.get("method").asString)
        assertEquals(true, func1.get("boundary")?.asBoolean, "boundaryfunc1's block is not marked a boundary")

        val entry = boxes.single { jsonLabel(it) == "entrypoint" }
        assertEquals("boundary.App#entrypoint(int,int,int)", entry.get("method").asString)
        assertEquals(null, entry.get("boundary"), "the entry point's block is marked a boundary")

        assertEquals(
            listOf("boundaryfunc1", "boundaryfunc2", "boundaryfunc2", "boundaryfunc3", "boundaryfunc3"),
            boxes.filter { it.get("boundary")?.asBoolean == true }.map { jsonLabel(it) }.sorted()
        )
    }

    /**
     * Every box but the root says where it was called from, so the hover can show the stack: two
     * calls of one method from two lines are two blocks with two `called`s. The entry point was
     * called by nothing and has none. Fails against a box naming its declaration instead.
     */
    @Test
    fun jsonNamesTheCallSiteOfEveryBoxButTheRoot() {
        val doc = jsonOf(boundaryRootBlocks())
        val boxes = jsonNodes(doc).filter { it.get("type").asString == "METHOD" }
        assertEquals(null, boxes.single { jsonLabel(it) == "entrypoint" }.get("called"), "the root has a call site")
        val func2 = boxes.filter { jsonLabel(it) == "boundaryfunc2" }.map { it.get("called")!!.asString }
        assertEquals(listOf("boundary/App.java:13", "boundary/App.java:17"), func2.map { it.substringBeforeLast(":") }.sorted())
        assertEquals(
            "result2 = Boundary.boundaryfunc2(result1, a);",
            doc.getAsJsonObject("lines").getAsJsonObject("boundary/App.java").get("13").asString
        )
    }

    /**
     * `lines` holds exactly the lines the nodes' sources (and the boxes' call sites) name, each as that line of the file,
     * trimmed. The text is checked against the file read here, so a line off by one fails.
     */
    @Test
    fun jsonCarriesTheTextOfEveryLineANodeNamesAndNoOther() {
        val doc = jsonOf(boundaryRootBlocks())
        val lines = doc.getAsJsonObject("lines")
        val named = jsonNodes(doc).flatMap { listOfNotNull(jsonSource(it)!!, it.get("called")?.asString) }
            .map { it.split(":") }
            .map { it[0] to it[1] }
            .toSet()
        val carried = lines.entrySet().flatMap { (file, texts) -> texts.asJsonObject.keySet().map { file to it } }.toSet()
        assertEquals(named, carried, "lines carries a line no node names, or misses one a node does")
        assertEquals(setOf("boundary/App.java", "boundary/Boundary.java"), lines.keySet())

        for ((file, line) in carried) {
            val expected = Files.readAllLines(testResourcesPath.resolve(file))[line.toInt() - 1].trim()
            assertEquals(expected, lines.getAsJsonObject(file).get(line).asString, "$file:$line")
        }
        assertEquals(
            "int result1 = Boundary.boundaryfunc1(a);",
            lines.getAsJsonObject("boundary/App.java").get("10").asString
        )
    }

    /** The three exporters render one graph, so they have to agree on its edges. */
    @Test
    fun jsonKeepsEveryEdgeTheMermaidGraphHas() {
        val mermaid = edgeLabels(buildGraph("funcCall", listOf("App.java")), events = true).sortedBy { it.toString() }
        val json = jsonEdgeLabels(buildJson("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        assertEquals(mermaid, json, "the two renderings of one graph disagree on its edges")
    }

    /**
     * The page has to carry its own libraries. A viewer that renders nothing because an asset was
     * missing looks exactly like a graph with no nodes, so the export fails loudly instead.
     */
    @Test
    fun htmlPageCarriesItsLibrariesAndItsData() {
        val page = StringBuilder()
        val testDirPath = testResourcesPath.resolve("funcCall")
        val roots = AstReader(testResourcesPath).process(listOf(testDirPath.resolve("App.java")))
        HtmlExporter("reactflow.bundle.js", testResourcesPath).processMainMethod(roots) { page.append(it).append("\n") }
        val html = page.toString()

        // Strings from inside the bundle, and string *literals* specifically: the bundle is minified,
        // so an identifier is renamed and a comment is gone, and the licence header and REVEAL_DEPTH
        // this used to look for now say nothing about whether anything was inlined. A library's own
        // name is no use either - it occurs in our code too, so asserting on it passed with not one
        // library present. Each of these three is written by exactly one of the three things that
        // have to be here: `react-flow__pane` by React Flow's own stylesheet, "Minified React error"
        // by the production React build, and `cf-box` by reactflow.tsx.
        assertTrue("react-flow__pane" in html, "the renderer was not inlined")
        assertTrue("Minified React error" in html, "React itself was not inlined")
        assertTrue("org.eclipse.elk" in html, "the layout engine was not inlined")
        assertTrue("cf-box" in html, "our own viewer code was not inlined")
        assertTrue("\"label\": \"methodC\"" in html, "the graph payload was not inlined")
        assertTrue("<script" in html && "</html>" in html, "the page is not a complete document")
    }

